/* ============================================
   IDP Carousel Component - Modern Design System
   ============================================ */

.zjpcy-carousel {
  position: relative;
  width: 100%;
  overflow: hidden;
  border-radius: var(--zjpcy-border-radius-lg);
  outline: none;
  box-shadow: var(--zjpcy-shadow-md);
}

.zjpcy-carousel:focus-visible {
  box-shadow: 0 0 0 2px var(--zjpcy-primary-color);
}

/* 内容区域 */

.zjpcy-carousel__content {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  transition-property: transform;
  transition-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

.zjpcy-carousel--vertical .zjpcy-carousel__content {
  flex-direction: column;
}

.zjpcy-carousel--fade .zjpcy-carousel__content {
  display: block;
}

/* 轮播项 */

.zjpcy-carousel__item {
  position: relative;
  width: 100%;
  height: 100%;
  flex-shrink: 0;
}

.zjpcy-carousel--fade .zjpcy-carousel__item {
  position: absolute;
  top: 0;
  left: 0;
  transition-property: opacity;
  transition-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

.zjpcy-carousel__item-inner {
  position: relative;
  width: 100%;
  height: 100%;
}

.zjpcy-carousel__image {
  width: 100%;
  height: 100%;
  -o-object-fit: cover;
     object-fit: cover;
  display: block;
  -webkit-user-select: none;
     -moz-user-select: none;
          user-select: none;
  -webkit-user-drag: none;
}

/* ============================================
   信息区域 - Modern Design
   ============================================ */

.zjpcy-carousel__info {
  position: absolute;
  color: #fff;
}

