  }

  .zjpcy-carousel--vertical .zjpcy-carousel__arrow {
    width: 36px;
    height: 36px;
  }

  .zjpcy-carousel__arrow svg {
    width: 20px;
    height: 20px;
  }

  .zjpcy-carousel--vertical .zjpcy-carousel__arrow--prev {
