/* ============================================
   IDP Cascader Component - Modern Design System
   ============================================ */

.cascader {
    position: relative;
    display: inline-block;
    box-sizing: border-box;
    font-size: 14px;
    line-height: 1.5715;
    color: var(--zjpcy-text-color);
    min-width: 180px;
    max-width: 100%;
}

/* ============================================
   触发器样式 - Modern Input Style
   ============================================ */

.cascader-trigger {
    position: relative;
    display: flex;
    align-items: center;
    min-height: 32px;
    padding: 6px 12px;
    background: linear-gradient(135deg, var(--zjpcy-bg-color-white) 0%, var(--zjpcy-bg-color) 100%);
    border: 1px solid var(--zjpcy-border-color-extra-light);
    border-radius: var(--zjpcy-border-radius-md);
    cursor: pointer;
    transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
    -webkit-user-select: none;
       -moz-user-select: none;
            user-select: none;
    overflow: hidden;
    box-shadow: var(--zjpcy-shadow-extra-light);
}

.cascader:hover:not(.cascader-disabled) .cascader-trigger {
    border-color: var(--zjpcy-primary-hover-color);
    box-shadow: var(--zjpcy-input-box-shadow-hover);
}

.cascader-open .cascader-trigger {
    border-color: var(--zjpcy-primary-color);
    box-shadow: var(--zjpcy-input-box-shadow-focus);
}

.cascader-disabled .cascader-trigger {
    color: var(--zjpcy-text-color-light);
    background: linear-gradient(135deg, var(--zjpcy-bg-color-light) 0%, var(--zjpcy-bg-color) 100%);
    cursor: not-allowed;
    opacity: var(--zjpcy-opacity-disabled);
}

/* ============================================
   选择区域样式
   ============================================ */

.cascader-selection-placeholder {
    color: var(--zjpcy-text-color-light);
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    padding-right: 10px;
    max-width: 100%;
}

.cascader-selection-value {
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    flex: 1;
    min-width: 0;
    max-width: calc(100% - 28px);
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    align-items: center;
    padding-right: 20px;
}

/* 有值时，选择区域的右侧留出清除按钮的空间 */

.cascader-has-value .cascader-selection-value {
    padding-right: 32px;
}

/* ============================================
   标签样式 - Modern Tag Style
   ============================================ */

.cascader-tag {
    display: inline-flex;
    align-items: center;
    padding: 2px 8px;
    background: linear-gradient(135deg, var(--zjpcy-bg-color-light) 0%, var(--zjpcy-bg-color) 100%);
    border: 1px solid var(--zjpcy-border-color-extra-light);
    border-radius: var(--zjpcy-border-radius-sm);
    font-size: 12px;
    line-height: 1.5;
    color: var(--zjpcy-text-color);
    max-width: -webkit-fill-available;
    transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
}

.cascader-tag:hover {
    border-color: var(--zjpcy-primary-color);
    box-shadow: var(--zjpcy-shadow-extra-light);
}

.cascader-tag-content {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: calc(100% - 16px);
}

.cascader-tag-close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-left: 4px;
    cursor: pointer;
    color: var(--zjpcy-text-color-tertiary);
    transition: all var(--zjpcy-transition-duration);
    flex-shrink: 0;
    width: 14px;
    height: 14px;
    border-radius: 50%;
}

.cascader-tag-close:hover {
    color: var(--zjpcy-error-color);
    background: rgba(245, 34, 45, 0.1);
}

.cascader-selection-hidden {
    display: none;
}

/* ============================================
   箭头与清除按钮
   ============================================ */

.cascader-arrow {
    flex-shrink: 0;
    margin-left: 5px;
    color: var(--zjpcy-text-color-tertiary);
    transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
    display: flex;
    align-items: center;
    position: absolute;
    right: 10px;
    width: 12px;
    justify-content: center;
}

.cascader-open .cascader-arrow {
    transform: rotate(180deg);
    color: var(--zjpcy-primary-color);
}

/* 当有值且鼠标悬停时，隐藏下拉箭头 */

.cascader-has-value:hover .cascader-arrow {
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
}

.cascader-clear {
    position: absolute;
    right: 8px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    flex-shrink: 0;
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.06);
    color: var(--zjpcy-text-color-tertiary);
    cursor: pointer;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-50%) scale(0.8) rotate(-45deg);
    transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
    z-index: 1;
}

/* 有值且悬停时，清除按钮显示，下拉箭头隐藏 */

.cascader-has-value:hover .cascader-clear {
    opacity: 1;
    visibility: visible;
