/* ============================================
   IDP Input Component - Modern Design System
   ============================================ */

/* ============================================
   标签样式
   ============================================ */

.input-label {
    font-size: 14px;
    color: var(--zjpcy-text-color);
    white-space: nowrap;
    flex-shrink: 0;
    font-weight: 500;
    letter-spacing: 0.2px;
}

/* ============================================
   输入框容器 - 主样式
   ============================================ */

.input-wrapper {
    width: 100%;
    position: relative;
    display: inline-flex;
    align-items: center;
    font-size: 14px;
    font-family: inherit;
    border: 1px solid var(--zjpcy-input-border);
    border-radius: var(--zjpcy-border-radius-lg);
    background: linear-gradient(135deg, var(--zjpcy-bg-color-white) 100%, var(--zjpcy-bg-color) 100%);
    transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
    outline: none;
    box-sizing: border-box;
    box-shadow: var(--zjpcy-shadow-extra-light);
    overflow: hidden;
    height: 36px;
}

.input-wrapper:hover {
    border-color: var(--zjpcy-input-border-hover);
    box-shadow: var(--zjpcy-input-box-shadow-hover);
}

/* ============================================
   输入框内部样式
   ============================================ */

.input-inner {
    flex: 1;
    min-width: 0;
    padding: 6px 12px;
    font-size: 14px;
    font-family: inherit;
    border: none;
    background-color: transparent;
    outline: none;
    box-sizing: border-box;
    color: var(--zjpcy-text-color);
    transition: color var(--zjpcy-transition-duration) ease;
}

.input-inner::-moz-placeholder {
    color: var(--zjpcy-text-color-light);
    opacity: 1;
    -moz-transition: color var(--zjpcy-transition-duration) ease;
    transition: color var(--zjpcy-transition-duration) ease;
}

.input-inner::placeholder {
    color: var(--zjpcy-text-color-light);
    opacity: 1;
    transition: color var(--zjpcy-transition-duration) ease;
}

.input-inner::-moz-placeholder {
    color: var(--zjpcy-text-color-light);
    opacity: 1;
}

.input-wrapper:hover .input-inner::-moz-placeholder {
    color: var(--zjpcy-text-color-tertiary);
}

.input-wrapper:hover .input-inner::placeholder {
    color: var(--zjpcy-text-color-tertiary);
}

/* ============================================
   前缀/后缀样式
   ============================================ */

.input-prefix {
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--zjpcy-text-color-tertiary);
    margin: 0 0 0 12px;
    transition: color var(--zjpcy-transition-duration) ease;
}

.input-wrapper:hover .input-prefix {
    color: var(--zjpcy-primary-hover-color);
}

.input-prefix .icon-container {
    padding: 0;
}

.input-suffix-group {
    display: flex;
    align-items: center;
    margin: 0 12px 0 8px;
    gap: 8px;
}

/* 清除按钮 */

.input-suffix-clear {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    flex-shrink: 0;
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.06);
    color: var(--zjpcy-text-color-tertiary);
    cursor: pointer;
    opacity: 0;
    visibility: hidden;
    transform: scale(0.8) rotate(-45deg);
    transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
}

.input-suffix-clear.visible {
    opacity: 1;
    visibility: visible;
    transform: scale(1) rotate(0deg);
}

.input-suffix-clear:hover {
    background: rgba(0, 0, 0, 0.12);
    color: var(--zjpcy-text-color-secondary);
    transform: scale(1.1);
}

.input-suffix-clear .icon-container {
    padding: 0;
}

.input-suffix-clear .icon {
    fill: currentColor;
}

.input-suffix-content {
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--zjpcy-text-color-tertiary);
    cursor: pointer;
    transition: all var(--zjpcy-transition-duration) ease;
}

.input-suffix-content:hover {
    color: var(--zjpcy-primary-hover-color);
    transform: scale(1.05);
}

.input-suffix-content .icon-container {
    padding: 0;
}

/* 兼容旧的suffix样式 */

.input-suffix {
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--zjpcy-text-color-tertiary);
    cursor: pointer;
    margin: 0 12px;
    transition: color var(--zjpcy-transition-duration) ease;
}

.input-suffix:hover {
    color: var(--zjpcy-primary-hover-color);
}

.input-suffix .icon-container {
    padding: 0;
}

/* ============================================
   NumberInput组件样式
   ============================================ */

.number-input-wrapper {
    display: flex;
    flex-direction: column;
    width: 100%;
}

/* ============================================
   InputBase容器样式
   ============================================ */

.input-base-container {
    display: flex;
    flex-direction: column;
    width: 100%;
}

/* ============================================
   提示信息样式
   ============================================ */

.input-extra {
    font-size: 12px;
    color: var(--zjpcy-text-color-tertiary);
    line-height: 1.5;
    padding: 6px 4px 0;
    text-align: left;
    transition: color var(--zjpcy-transition-duration) ease;
}

.input-wrapper:hover ~ .input-extra {
    color: var(--zjpcy-text-color-secondary);
}

/* ============================================
   错误状态样式
   ============================================ */

.input-error {
    border-color: var(--zjpcy-error-color) !important;
    box-shadow: 0 2px 4px rgba(245, 34, 45, 0.1) !important;
}

.input-error:hover,
.input-error:focus-within {
    border-color: #ff7875 !important;
    box-shadow: 0 4px 12px rgba(245, 34, 45, 0.15), 0 0 0 3px rgba(245, 34, 45, 0.08) !important;
}

/* 错误消息动画 - 从上而下淡入 */

.input-error-message {
    font-size: 12px;
    color: var(--zjpcy-error-color);
    line-height: 1.5;
    padding: 6px 4px 0;
    text-align: left;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);
    transform-origin: top center;
    border-radius: var(--zjpcy-border-radius-sm);
    transition:
        opacity var(--zjpcy-transition-duration) cubic-bezier(0.16, 1, 0.3, 1),
        visibility var(--zjpcy-transition-duration) cubic-bezier(0.16, 1, 0.3, 1),
        transform var(--zjpcy-transition-duration) cubic-bezier(0.16, 1, 0.3, 1);
    max-height: 50px;
    overflow: hidden;
    white-space: normal;
    word-wrap: break-word;
    position: relative;
    z-index: 10;
}

/* 当错误消息显示时，从上而下淡入 */

.input-error-message.visible {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
    transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
}

/* 当错误消息消失时，从下而上淡出 */

.input-error-message:not(.visible) {
    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);
    transition-timing-function: cubic-bezier(0.55, 0, 0.1, 1);
}

/* ============================================
   禁用和只读状态
   ============================================ */

.input-wrapper-disabled {
    background: linear-gradient(135deg, var(--zjpcy-bg-color-light) 0%, var(--zjpcy-bg-color) 100%);
    border-color: var(--zjpcy-border-color-extra-light);
    color: var(--zjpcy-text-color-light);
    cursor: not-allowed;
    box-shadow: none;
}

.input-wrapper-disabled:hover {
    box-shadow: none;
    border-color: var(--zjpcy-border-color-extra-light);
}

.input-wrapper-disabled .input-inner {
    background-color: transparent;
    color: var(--zjpcy-text-color-light);
    cursor: not-allowed;
}

.input-wrapper-readonly {
    background: linear-gradient(135deg, var(--zjpcy-bg-color) 0%, var(--zjpcy-bg-color-light) 100%);
    border-color: var(--zjpcy-border-color);
    cursor: default;
}

.input-wrapper-readonly:hover {
    box-shadow: var(--zjpcy-shadow-extra-light);
    border-color: var(--zjpcy-border-color-extra-light);
}

.input-wrapper-readonly .input-inner {
    background-color: transparent;
    cursor: default;
}

/* ============================================
   聚焦状态
   ============================================ */

.input-wrapper:focus-within {
    border-color: var(--zjpcy-input-border-focus);
    box-shadow: var(--zjpcy-input-box-shadow-focus);
    background: var(--zjpcy-bg-color-white);
}

/* ============================================
   兼容旧的input样式
   ============================================ */

.input {
    padding: 6px 12px;
    font-size: 14px;
    font-family: inherit;
    border: 1px solid var(--zjpcy-border-color-extra-light);
    border-radius: var(--zjpcy-border-radius-lg);
    background: linear-gradient(135deg, var(--zjpcy-bg-color-white) 0%, var(--zjpcy-bg-color) 100%);
    transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
    outline: none;
    box-sizing: border-box;
    display: inline-block;
    box-shadow: var(--zjpcy-shadow-extra-light);
}

.input:hover {
    border-color: var(--zjpcy-primary-hover-color);
    box-shadow: var(--zjpcy-input-box-shadow-hover);
}

.input:focus {
    border-color: var(--zjpcy-primary-color);
    box-shadow: var(--zjpcy-input-box-shadow-focus);
    background: var(--zjpcy-bg-color-white);
}

/* ============================================
   搜索输入框样式
   ============================================ */

.search-input-wrapper {
    position: relative;
    display: inline-block;
}

.search-input-suffix {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    align-items: center;
    pointer-events: none;
    gap: 8px;
}

.search-input-suffix svg {
    pointer-events: all;
    transition: all var(--zjpcy-transition-duration) ease;
}

.search-input-suffix svg:hover {
    transform: scale(1.1);
    color: var(--zjpcy-primary-color);
}

/* ============================================
   Textarea 样式
   ============================================ */

.textarea-wrapper {
    display: inline-flex;
    flex-direction: column;
    font-size: 14px;
    font-family: inherit;
}

.textarea-input-wrapper {
    width: 100%;
    position: relative;
    display: flex;
    align-items: flex-start;
    border: 1px solid var(--zjpcy-border-color-extra-light);
    border-radius: var(--zjpcy-border-radius-lg);
    background: linear-gradient(135deg, var(--zjpcy-bg-color-white) 0%, var(--zjpcy-bg-color) 100%);
    transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
    outline: none;
    box-sizing: border-box;
    box-shadow: var(--zjpcy-shadow-extra-light);
    overflow: hidden;
}

.textarea-input-wrapper:hover {
    border-color: var(--zjpcy-input-border-hover);
    box-shadow: var(--zjpcy-input-box-shadow-hover);
}

.textarea-input-wrapper-focused {
    border-color: var(--zjpcy-input-border-focus);
    box-shadow: var(--zjpcy-input-box-shadow-focus);
    background: var(--zjpcy-bg-color-white);
}

.textarea-input-wrapper-disabled {
    background: linear-gradient(135deg, var(--zjpcy-bg-color-light) 0%, var(--zjpcy-bg-color) 100%);
    border-color: var(--zjpcy-border-color-extra-light);
    color: var(--zjpcy-text-color-light);
    cursor: not-allowed;
    box-shadow: none;
}

.textarea-input-wrapper-disabled:hover {
    box-shadow: none;
    border-color: var(--zjpcy-border-color-extra-light);
}

.textarea-input-wrapper-readonly {
    background: linear-gradient(135deg, var(--zjpcy-bg-color) 0%, var(--zjpcy-bg-color-light) 100%);
    border-color: var(--zjpcy-border-color);
    cursor: default;
}

.textarea-input-wrapper-readonly:hover {
    box-shadow: var(--zjpcy-shadow-extra-light);
    border-color: var(--zjpcy-border-color-extra-light);
}

.textarea-base {
    width: 100%;
    font-size: 14px;
    font-family: inherit;
    border: none;
    background-color: transparent;
    outline: none;
    box-sizing: border-box;
    resize: none;
    line-height: 1.6;
    padding: 12px;
    color: var(--zjpcy-text-color);
    min-height: 80px;
}

.textarea-base::-moz-placeholder {
    color: var(--zjpcy-text-color-light);
    opacity: 1;
}

.textarea-base::placeholder {
    color: var(--zjpcy-text-color-light);
    opacity: 1;
}

.textarea-base::-moz-placeholder {
    color: var(--zjpcy-text-color-light);
    opacity: 1;
}

.textarea-input-wrapper:hover .textarea-base::-moz-placeholder {
    color: var(--zjpcy-text-color-tertiary);
}

.textarea-input-wrapper:hover .textarea-base::placeholder {
    color: var(--zjpcy-text-color-tertiary);
}

.textarea-base:disabled {
    background-color: transparent;
    color: var(--zjpcy-text-color-light);
    cursor: not-allowed;
}

.textarea-base:-moz-read-only {
    background-color: transparent;
    cursor: default;
}

.textarea-base:read-only {
    background-color: transparent;
    cursor: default;
}

.textarea-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
}

.textarea-clear {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.06);
    color: var(--zjpcy-text-color-tertiary);
    cursor: pointer;
    opacity: 0.8;
    transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
}

.textarea-clear:hover {
    opacity: 1;
    background: rgba(0, 0, 0, 0.12);
    color: var(--zjpcy-text-color-secondary);
    transform: scale(1.1) rotate(90deg);
}

.textarea-count {
    font-size: 12px;
    color: var(--zjpcy-text-color-tertiary);
    font-weight: 500;
    transition: color var(--zjpcy-transition-duration) ease;
}

.textarea-wrapper:focus-within .textarea-count {
    color: var(--zjpcy-primary-color);
}

/* Textarea 拖拽手柄 */

.textarea-resize-handle {
    opacity: 0;
    transition: all var(--zjpcy-transition-duration) ease;
}

.textarea-input-wrapper:hover .textarea-resize-handle {
    opacity: 0.6;
}

.textarea-input-wrapper.resizing .textarea-resize-handle {
    opacity: 1;
}

.textarea-input-wrapper.resizing {
    -webkit-user-select: none;
       -moz-user-select: none;
            user-select: none;
}

.textarea-input-wrapper.resizing textarea {
    cursor: nwse-resize;
}

/* ============================================
   焦点可见性样式
   ============================================ */

.input-wrapper:focus-visible,
.textarea-input-wrapper:focus-visible {
    outline: 2px solid var(--zjpcy-primary-color);
    outline-offset: 2px;
}

/* ============================================
   过渡动画关键帧
   ============================================ */

@keyframes input-glow {
    0%, 100% {
        box-shadow: var(--zjpcy-input-box-shadow-focus);
    }
    50% {
        box-shadow: 0 4px 16px rgba(24, 144, 255, 0.3), 0 0 0 4px rgba(24, 144, 255, 0.15);
    }
}

.input-wrapper:focus-within {
    animation: input-glow 2s ease-in-out infinite;
}

.marquee-container {
    position: relative;
    width: 100%;
    overflow: hidden;
    white-space: nowrap;
    display: flex;
    align-items: center;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.marquee-container-fixed {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 99999;
}

.marquee-text {
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    display: flex;
    align-items: center;
    font-size: 14px;
    color: #333;
    padding: 0 10px;
}

.marquee-close {
    position: absolute;
    right: 0;
    top: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 10;
}

/* ============================================
   IDP Message Component - Modern Design System
   ============================================ */

/* 消息提示框基础样式 */

.zjpcy-message {
  position: fixed;
  top: 20px;
  left: 50%;
  transform: translateX(-50%) translateY(-100%);
  width: auto;
  max-width: 800px;
  min-width: auto;
  height: auto;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--zjpcy-bg-color-white) 0%, var(--zjpcy-bg-color) 100%);
  border-radius: var(--zjpcy-border-radius-lg);
  box-shadow: var(--zjpcy-shadow-md);
  z-index: var(--zjpcy-z-index-message);
  opacity: 0;
  transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
  pointer-events: auto;
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
}

/* 显示状态 */

.zjpcy-message--show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* 消息内容容器 */

.zjpcy-message-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 100%;
  padding: 12px 24px;
}

/* 消息文本 */

.zjpcy-message-text {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
  color: var(--zjpcy-text-color);
  white-space: nowrap;
  text-align: left;
  letter-spacing: 0.2px;
}

/* ============================================
   成功类型样式
   ============================================ */

.zjpcy-message--success {
  background: linear-gradient(135deg, rgba(82, 196, 26, 0.08) 0%, rgba(82, 196, 26, 0.04) 100%);
  border: 1px solid rgba(82, 196, 26, 0.3);
  box-shadow: 0 4px 16px rgba(82, 196, 26, 0.15), var(--zjpcy-shadow-sm);
}

.zjpcy-message--success .zjpcy-message-text {
  color: var(--zjpcy-success-color);
  font-weight: 600;
}

/* ============================================
   警告类型样式
   ============================================ */

.zjpcy-message--warning {
  background: linear-gradient(135deg, rgba(250, 173, 20, 0.08) 0%, rgba(250, 173, 20, 0.04) 100%);
  border: 1px solid rgba(250, 173, 20, 0.3);
  box-shadow: 0 4px 16px rgba(250, 173, 20, 0.15), var(--zjpcy-shadow-sm);
}

.zjpcy-message--warning .zjpcy-message-text {
  color: var(--zjpcy-warning-color);
  font-weight: 600;
}

/* ============================================
   错误类型样式
   ============================================ */

.zjpcy-message--error {
  background: linear-gradient(135deg, rgba(245, 34, 45, 0.08) 0%, rgba(245, 34, 45, 0.04) 100%);
  border: 1px solid rgba(245, 34, 45, 0.3);
  box-shadow: 0 4px 16px rgba(245, 34, 45, 0.15), var(--zjpcy-shadow-sm);
}

.zjpcy-message--error .zjpcy-message-text {
  color: var(--zjpcy-error-color);
  font-weight: 600;
}

/* ============================================
   信息类型样式 (默认)
   ============================================ */

.zjpcy-message--info {
  background: linear-gradient(135deg, rgba(24, 144, 255, 0.08) 0%, rgba(24, 144, 255, 0.04) 100%);
  border: 1px solid rgba(24, 144, 255, 0.3);
  box-shadow: 0 4px 16px rgba(24, 144, 255, 0.15), var(--zjpcy-shadow-sm);
}

.zjpcy-message--info .zjpcy-message-text {
  color: var(--zjpcy-primary-color);
  font-weight: 600;
}

/* ============================================
   动画效果
   ============================================ */

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(-100%) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1);
  }
}

@keyframes slideUp {
  from {
    opacity: 1;
    transform: translateX(-50%) translateY(0) scale(1);
  }
  to {
    opacity: 0;
    transform: translateX(-50%) translateY(-100%) scale(0.95);
  }
}

/* 显示动画 */

.zjpcy-message--show {
  animation: slideDown 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

/* 隐藏动画 */

.zjpcy-message:not(.zjpcy-message--show) {
  animation: slideUp 0.25s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

/* ============================================
   响应式设计
   ============================================ */

@media (max-width: 768px) {
  .zjpcy-message {
    max-width: 90vw;
    top: 16px;
  }

  .zjpcy-message-content {
    padding: 10px 16px;
    gap: 8px;
  }

  .zjpcy-message-text {
    font-size: 13px;
  }
}

/* ============================================
   IDP Design System - 全局 CSS 变量
   ============================================ */

/* ============================================
   ANTI-FOUC: SSR 闪烁防护
   确保服务端渲染期间有正确的默认样式
   ============================================ */

/* 基础防护：确保 HTML 和 body 默认使用亮色背景 */

html, body {
  background-color: #ffffff;
}

/* 主题颜色变量定义 */

:root {
  /* 主色调 - 主要用于强调和突出显示 */
  --zjpcy-primary-color: #1890ff; /* 主色调基础色 - 用于按钮、链接等主要交互元素 */
  --zjpcy-primary-hover-color: #40a9ff; /* 主色调悬停色 - 用于鼠标悬停状态 */
  --zjpcy-primary-light-color: rgba(24, 100, 240, 0.1); /* 主色调浅色 - 用于多选选中背景等 */
  
  /* 辅助色 - 用于不同状态和场景 */
  --zjpcy-success-color: #52c41a; /* 成功色 - 用于成功状态、确认操作等 */
  --zjpcy-warning-color: #faad14; /* 警告色 - 用于警告提示、需要注意的操作等 */
  --zjpcy-error-color: #f5222d; /* 错误色 - 用于错误提示、危险操作等 */
  --zjpcy-info-color: #1890ff; /* 信息色 - 用于普通信息提示 */
  --zjpcy-secondary-color: #fff; /* 次要色 - 用于次要按钮、辅助文本等 */
  --zjpcy-secondary-border-color: #d9d9d9; /* 次要边框色 - 用于次要按钮、辅助文本等 */
  --zjpcy-primary-secondary-border-color: #1890ff; /* 主要次要边框色 - 用于主要次要按钮、辅助文本等 */

  /* 中性色 - 用于文本、边框、背景等基础元素 */
  --zjpcy-text-color: rgba(0, 0, 0, 0.85); /* 主要文本色 - 用于正文、标题等 */
  --zjpcy-text-color-secondary: rgba(0, 0, 0, 0.65); /* 次要文本色 - 用于副标题、辅助说明等 */
  --zjpcy-text-color-tertiary: rgba(0, 0, 0, 0.45); /*  tertiary文本色 - 用于次要信息、提示文字等 */
  --zjpcy-text-color-light: #bfbfbf; /* 浅色文本 - 用于禁用状态、占位符等 */
  --zjpcy-border-color: #e8e8e8; /* 基础边框色 - 用于容器、分割线等 */
  --zjpcy-border-color-light: #f0f0f0; /* 浅色边框 - 用于次要分割、卡片边框等 */
  --zjpcy-border-color-extra-light: #d9d9d9; /* 超浅色边框 - 用于输入框、表格边框等 */
  --zjpcy-bg-color: #fafafa; /* 基础背景色 - 用于页面背景、容器背景等 */
  --zjpcy-bg-color-light: #f5f5f5; /* 浅色背景 - 用于卡片、组件背景等 */
  --zjpcy-bg-color-white: #fff; /* 白色背景 - 用于主要内容区域、弹窗等 */
  
  /* 阴影效果 - 用于组件的悬浮和层次感 */
  --zjpcy-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.15); /* 小阴影 - 用于轻微悬浮效果 */
  --zjpcy-shadow-md: 0 4px 12px rgba(0, 0, 0, 0.15); /* 中阴影 - 用于卡片、弹窗等 */
  --zjpcy-shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.15); /* 大阴影 - 用于模态框、下拉菜单等 */
  --zjpcy-shadow-extra-light: 0 2px 8px rgba(0, 0, 0, 0.08); /* 超浅阴影 - 用于轻微凸起效果 */
  
  /* 圆角 - 用于组件的边角处理 */
  --zjpcy-border-radius-sm: 2px; /* 小圆角 - 用于按钮、输入框等小组件 */
  --zjpcy-border-radius-md: 6px; /* 中圆角 - 用于卡片、弹窗等中等组件 */
  --zjpcy-border-radius-lg: 4px; /* 大圆角 - 用于模态框、特殊容器等 */
  
  /* 动画 - 用于过渡和动效 */
  --zjpcy-transition-duration: 0.2s; /* 过渡动画持续时间 - 控制动画快慢 */
  --zjpcy-transition-timing-function: ease-in-out; /* 过渡动画缓动函数 - 控制动画节奏 */
  
  /* 透明度 - 用于元素的显示状态 */
  --zjpcy-opacity-disabled: 0.65; /* 禁用状态透明度 - 用于禁用的按钮、输入框等 */
  
  /* z-index - 用于控制元素的堆叠顺序 */
  --zjpcy-z-index-modal: 1000; /* 模态框层级 - 确保模态框在最上层 */
  --zjpcy-z-index-message: 1050; /* 消息提示层级 - 确保消息提示在模态框之上 */
  --zjpcy-z-index-marquee-fixed: 99999; /* 跑马灯固定层级 - 确保跑马灯始终在最顶层 */
  
  /* Button 组件 - 按钮相关样式变量 */
  --zjpcy-button-primary-bg: var(--zjpcy-primary-color); /* 主要按钮背景色 */
  --zjpcy-button-primary-border: var(--zjpcy-primary-color); /* 主要按钮边框色 */
  --zjpcy-button-primary-hover-bg: var(--zjpcy-primary-hover-color); /* 主要按钮悬停背景色 */
  --zjpcy-button-primary-hover-border: var(--zjpcy-primary-hover-color); /* 主要按钮悬停边框色 */
  --zjpcy-button-primary-active-shadow: 0 4px 8px rgba(24, 144, 255, 0.4); /* 主要按钮激活阴影 */
  
  --zjpcy-button-secondary-bg: var(--zjpcy-secondary-color); /* 次要按钮背景色 */
  --zjpcy-button-secondary-border: var(--zjpcy-secondary-border-color); /* 次要按钮边框色 */
  --zjpcy-button-secondary-hover-bg: var(--zjpcy-secondary-color); /* 次要按钮悬停背景色 */
  --zjpcy-button-secondary-hover-border: var(--zjpcy-primary-secondary-border-color); /* 次要按钮悬停边框色 */
  --zjpcy-button-secondary-active-shadow: 0 4px 8px rgba(108, 117, 125, 0.4); /* 次要按钮激活阴影 */
  
  --zjpcy-button-danger-bg: var(--zjpcy-error-color); /* 危险按钮背景色 */
