                0 6px 16px 0 rgba(0, 0, 0, 0.08),
                0 9px 28px 8px rgba(0, 0, 0, 0.05);
    line-height: 1.5;
    pointer-events: auto;
    opacity: 0;
    transform: scale(0.95);
    transition: opacity 0.2s cubic-bezier(0.4, 0, 0.2, 1),
                transform 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.zjpcy-tooltip.is-visible {
    opacity: 1;
    transform: scale(1);
}

/* 不同方向的动画偏移 */

.zjpcy-tooltip-top {
    transform-origin: center bottom;
    transform: scale(0.95) translateY(8px);
}

.zjpcy-tooltip-top.is-visible {
    transform: scale(1) translateY(0);
}

.zjpcy-tooltip-bottom {
    transform-origin: center top;
    transform: scale(0.95) translateY(-8px);
}

.zjpcy-tooltip-bottom.is-visible {
    transform: scale(1) translateY(0);
}

.zjpcy-tooltip-left {
    transform-origin: right center;
    transform: scale(0.95) translateX(8px);
}

.zjpcy-tooltip-left.is-visible {
    transform: scale(1) translateX(0);
}

.zjpcy-tooltip-right {
    transform-origin: left center;
    transform: scale(0.95) translateX(-8px);
}

.zjpcy-tooltip-right.is-visible {
    transform: scale(1) translateX(0);
}

.zjpcy-tooltip-content {
    position: relative;
    z-index: 1;
}

.zjpcy-tooltip-arrow {
    position: absolute;
    width: var(--tooltip-arrow-size);
    height: var(--tooltip-arrow-size);
    background-color: var(--tooltip-bg-color);
    transform: rotate(45deg);
}

/* Top placement */

.zjpcy-tooltip-top .zjpcy-tooltip-arrow {
    bottom: calc(var(--tooltip-arrow-size) * -0.5);
    left: 50%;
    margin-left: calc(var(--tooltip-arrow-size) * -0.5);
}

/* Bottom placement */

.zjpcy-tooltip-bottom .zjpcy-tooltip-arrow {
    top: calc(var(--tooltip-arrow-size) * -0.5);
    left: 50%;
    margin-left: calc(var(--tooltip-arrow-size) * -0.5);
}

/* Left placement */

.zjpcy-tooltip-left .zjpcy-tooltip-arrow {
    right: calc(var(--tooltip-arrow-size) * -0.5);
    top: 50%;
    margin-top: calc(var(--tooltip-arrow-size) * -0.5);
}

/* Right placement */

.zjpcy-tooltip-right .zjpcy-tooltip-arrow {
    left: calc(var(--tooltip-arrow-size) * -0.5);
    top: 50%;
    margin-top: calc(var(--tooltip-arrow-size) * -0.5);
}

