/* ============================================
   IDP Anchor Component - Modern Design System
   ============================================ */

.zjpcy-anchor {
  position: relative;
  padding: 3px;
  background: linear-gradient(
    180deg,
    var(--zjpcy-bg-color-white) 0%,
    var(--zjpcy-bg-color) 100%
  );
  border-radius: var(--zjpcy-border-radius-lg);
  box-shadow: var(--zjpcy-shadow-sm);
  border: 1px solid var(--zjpcy-border-color-light);
  height: auto;
}

.zjpcy-anchor-affix {
  position: fixed;
  top: 20px;
  left: 20px;
  z-index: 100;
}

.zjpcy-anchor-list {
  list-style: none;
  padding: 0;
  margin: 0;
  position: relative;
}

/* 左侧指示线 */

.zjpcy-anchor-list::before {
  content: '';
  position: absolute;
  left: 0;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background: var(--zjpcy-border-color);
  border-radius: 1px;
}

.zjpcy-anchor-link {
  margin: 4px 0;
  padding: 0;
  position: relative;
}

.zjpcy-anchor-link-a {
  display: block;
  padding: 2px;
  color: var(--zjpcy-text-color-secondary);
  text-decoration: none;
  border-radius: var(--zjpcy-border-radius-md);
  transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
  font-size: 13px;
  line-height: 1.5;
  font-weight: 400;
  margin-left: 8px;
}

.zjpcy-anchor-link-a:hover {
  color: var(--zjpcy-primary-color);
  background: var(--zjpcy-primary-light-color);
}

/* 激活状态 */

.zjpcy-anchor-link-active {
  position: relative;
}

/* 激活指示器 - 使用 transition 替代 animation 避免跳动 */

.zjpcy-anchor-link::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%) scaleY(0);
  width: 3px;
  height: 20px;
  background: var(--zjpcy-primary-color);
  border-radius: 0 2px 2px 0;
  box-shadow: 2px 0 8px rgba(24, 144, 255, 0.3);
  opacity: 0;
  transition:
    transform 0.25s cubic-bezier(0.4, 0, 0.2, 1),
    opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.zjpcy-anchor-link-active::before {
  transform: translateY(-50%) scaleY(1);
  opacity: 1;
}

.zjpcy-anchor-link-active .zjpcy-anchor-link-a {
  color: var(--zjpcy-primary-color);
  background: var(--zjpcy-primary-light-color);
  font-weight: 500;
}

/* 滚动定位时的平滑过渡 */

html {
  scroll-behavior: smooth;
}

/* 响应式适配 */

@media (max-width: 768px) {
  .zjpcy-anchor-affix {
    position: static;
    margin-bottom: 24px;
  }
  
  .zjpcy-anchor {
    padding: 16px;
  }
  
  .zjpcy-anchor-link-a {
    padding: 10px 14px;
  }
}

.breadcrumb {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
  font-size: 14px;
  line-height: 1.5;
}

.breadcrumb-list {
  display: flex;
  align-items: center;
  list-style: none;
  margin: 0;
  padding: 0;
  gap: 8px;
}

.breadcrumb-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.breadcrumb-link {
  display: inline-flex;
  color: #666;
  text-decoration: none;
  transition: color 0.2s ease;
  position: relative;
}

.breadcrumb-link:hover {
  color: #333;
  text-decoration: none;
}

.breadcrumb-link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 50%;
  width: 0;
  height: 2px;
  background-color: #339af0;
  transition: all 0.3s ease;
  transform: translateX(-50%);
}

.breadcrumb-link:hover::after {
  width: 100%;
  left: 0;
  transform: translateX(0);
}

.breadcrumb-text {
  color: #666;
}

.breadcrumb-current {
  color: #000;
  font-weight: 500;
}

.breadcrumb-separator {
  color: #999;
  font-weight: 300;
}
