/* ============================================
   下拉组件基础
   ============================================ */

.dropdown {
  position: relative;
  display: inline-block;
}

.dropdown-content-wrapper {
  position: relative;
}

.dropdown--disabled {
  opacity: var(--zjpcy-opacity-disabled);
  cursor: not-allowed;
}

/* ============================================
   触发器样式
   ============================================ */

.dropdown-trigger {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border: 1px solid var(--zjpcy-border-color-extra-light);
  border-radius: var(--zjpcy-border-radius-lg);
  background: linear-gradient(135deg, var(--zjpcy-bg-color-white) 0%, var(--zjpcy-bg-color) 100%);
  cursor: pointer;
  transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
  -webkit-user-select: none;
     -moz-user-select: none;
          user-select: none;
  box-shadow: var(--zjpcy-shadow-extra-light);
  font-size: 14px;
  color: var(--zjpcy-text-color);
}

.dropdown-trigger:hover {
  border-color: var(--zjpcy-primary-hover-color);
  box-shadow: var(--zjpcy-shadow-sm);
}

/* 纯文本触发器 */

.dropdown-trigger--text {
  border: none;
  background: transparent;
  padding: 4px 8px;
  color: var(--zjpcy-primary-color);
  box-shadow: none;
}

.dropdown-trigger--text:hover {
  background: var(--zjpcy-primary-light-color);
  color: var(--zjpcy-primary-hover-color);
  box-shadow: none;
}

/* 禁用状态 */

.dropdown-trigger--disabled {
  cursor: not-allowed;
  opacity: var(--zjpcy-opacity-disabled);
  background: var(--zjpcy-input-disabled-bg);
  border-color: var(--zjpcy-input-disabled-border);
}

.dropdown-trigger--disabled:hover {
  border-color: var(--zjpcy-input-disabled-border);
  box-shadow: none;
}

/* ============================================
   下拉箭头
   ============================================ */

.dropdown-arrow {
  transition: transform var(--zjpcy-transition-duration) ease;
  font-size: 12px;
  color: var(--zjpcy-text-color-tertiary);
}

.dropdown:hover .dropdown-arrow {
  transform: rotate(180deg);
  color: var(--zjpcy-primary-color);
}

/* ============================================
   下拉菜单
   ============================================ */

.dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
  min-width: 160px;
  background: linear-gradient(180deg, var(--zjpcy-bg-color-white) 0%, var(--zjpcy-bg-color-white) 100%);
  border: 1px solid var(--zjpcy-border-color-light);
  border-radius: var(--zjpcy-border-radius-lg);
  box-shadow: var(--zjpcy-shadow-lg);
  z-index: 1050;
  opacity: 0;
  transform: translateY(-8px) scale(0.96);
  transform-origin: top center;
  transition:
    opacity 0.2s cubic-bezier(0.23, 1, 0.32, 1),
