:root {
  /* 禁用状态透明度 */
  --rate-disabled-opacity: 0.6;
  
  /* 星星间距 */
  --rate-star-gap: 5px;
  
  /* hover 放大比例 */
  --rate-hover-scale: 1.15;
  
  /* 过渡动画时间 */
  --rate-transition-fast: 0.2s;
  --rate-transition-medium: 0.3s;
  
  /* 过渡动画曲线 */
  --rate-transition-timing: cubic-bezier(0.4, 0, 0.2, 1);
  
  /* 半星宽度 */
  --rate-half-width: 50%;
  
  /* 全星宽度 */
  --rate-full-width: 100%;
  
  /* 空星宽度 */
  --rate-empty-width: 0;
  
  /* 空星透明度 */
  --rate-empty-opacity: 0;
  
  /* 层级索引 */
  --rate-z-index: 2;
  
  /* 鼠标样式 */
  --rate-cursor-pointer: pointer;
  --rate-cursor-not-allowed: not-allowed;
  
  /* 指针事件 */
  --rate-pointer-events-none: none;
  
  /* chats 模式尺寸 */
  --rate-chats-size: 1em;
  
  /* chats 模式圆角 */
  --rate-chats-radius: 2px;
}

.rate {
  display: inline-flex;
  align-items: center;
  cursor: var(--rate-cursor-pointer);
  -webkit-user-select: none;
     -moz-user-select: none;
          user-select: none;
  gap: var(--rate-star-gap);
  justify-content: center;
}

.rate-disabled {
  cursor: var(--rate-cursor-not-allowed);
  opacity: var(--rate-disabled-opacity);
}

.rate-star {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--rate-transition-fast) var(--rate-transition-timing);
  will-change: transform;
  -webkit-user-select: none;
     -moz-user-select: none;
          user-select: none;
}

/* 只在默认星星模式下启用hover放大效果 */

.rate-star-mode .rate-star:hover {
  transform: scale(var(--rate-hover-scale));
}

.rate-disabled .rate-star:hover {
  transform: none;
}

.rate-star-bg {
  display: block;
  transition: all var(--rate-transition-fast) var(--rate-transition-timing);
  will-change: transform, color, opacity;
  pointer-events: var(--rate-pointer-events-none); /* 背景图标不响应事件 */
}

.rate-star-fill {
  position: absolute;
  left: 0;
  top: 0;
  width: var(--rate-empty-width);
  height: 100%;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  pointer-events: var(--rate-pointer-events-none); /* 前景图标不响应事件 */
  transition: width var(--rate-transition-medium) var(--rate-transition-timing), opacity var(--rate-transition-medium) var(--rate-transition-timing);
  will-change: width, opacity;
}

.rate-star-fill-half {
  width: var(--rate-half-width);
  opacity: 1;
}

.rate-star-fill-full {
  width: var(--rate-full-width);
  opacity: 1;
}

/* 确保空星状态完全隐藏 */

.rate-star-fill-empty {
  width: var(--rate-empty-width);
  opacity: var(--rate-empty-opacity);
}

.rate-star-fill .rate-star-icon {
  flex-shrink: 0;
}

/* 左半区域 - 控制半星 */

.rate-star-left {
  position: absolute;
  left: 0;
  top: 0;
  width: var(--rate-half-width);
  height: 100%;
  cursor: var(--rate-cursor-pointer);
  z-index: var(--rate-z-index); /* 确保在图标上方 */
}

/* 右半区域 - 控制全星 */

.rate-star-right {
  position: absolute;
  right: 0;
  top: 0;
  width: var(--rate-half-width);
  height: 100%;
  cursor: var(--rate-cursor-pointer);
  z-index: var(--rate-z-index); /* 确保在图标上方 */
}

.rate-disabled .rate-star-left,
.rate-disabled .rate-star-right,
.rate-disabled .rate-character-full {
  cursor: var(--rate-cursor-not-allowed);
}

