  height: 100%;
  background: var(--zjpcy-slider-track-filled-bg);
  border-radius: var(--zjpcy-slider-track-border-radius);
  box-shadow: 0 1px 2px rgba(24, 144, 255, 0.2);
  will-change: width;
}

/* 滑块手柄 - 使用 left 百分比定位 */

.slider-handle {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: var(--zjpcy-slider-handle-size);
  height: var(--zjpcy-slider-handle-size);
  background: var(--zjpcy-slider-handle-bg);
  border: var(--zjpcy-slider-handle-border);
  border-radius: 50%;
  cursor: grab;
  box-shadow: var(--zjpcy-slider-handle-shadow);
  transition: box-shadow var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function),
              border-color var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
  z-index: 2;
  will-change: left;
}

.slider-handle:hover {
  box-shadow: var(--zjpcy-slider-handle-shadow-hover);
}

.slider-handle:active {
  cursor: grabbing;
  box-shadow: var(--zjpcy-slider-handle-shadow-active);
}

/* 拖动时完全禁用过渡 - 直接响应鼠标移动 */

.slider-container-dragging .slider-handle {
  transition: none;
}

/* 禁用状态 */

.slider-container-disabled .slider-track {
  background: var(--zjpcy-slider-disabled-track-bg);
  cursor: not-allowed;
  box-shadow: none;
}

.slider-container-disabled .slider-track-filled {
  background: var(--zjpcy-slider-disabled-filled-bg);
  box-shadow: none;
}

.slider-container-disabled .slider-handle {
  background: var(--zjpcy-bg-color-white);
  border-color: var(--zjpcy-slider-disabled-handle-border);
  cursor: not-allowed;
  box-shadow: none;
}

/* 标记点 */

.slider-marks {
  position: relative;
  margin-top: 10px;
  height: 20px;
}

.slider-mark {
  position: absolute;
  transform: translateX(-50%);
  font-size: 12px;
  color: var(--zjpcy-slider-mark-color);
  font-weight: 400;
  transition: color var(--zjpcy-transition-duration) ease;
}

.slider-mark::before {
  content: '';
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  width: 1px;
  height: 6px;
  background-color: var(--zjpcy-slider-mark-line-bg);
  transition: background-color var(--zjpcy-transition-duration) ease;
}

/* 值显示 */

.slider-value-display {
  margin-top: 12px;
  font-size: 14px;
  color: var(--zjpcy-slider-value-color);
  font-weight: 500;
  text-align: center;
}

/* 工具提示 */

.slider-tooltip {
  position: absolute;
  top: -36px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--zjpcy-slider-tooltip-bg);
  color: var(--zjpcy-slider-tooltip-color);
  padding: 4px 10px;
  border-radius: var(--zjpcy-border-radius-sm);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: all var(--zjpcy-transition-duration) ease;
  box-shadow: var(--zjpcy-slider-tooltip-shadow);
}

.slider-tooltip::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 4px solid transparent;
  border-top-color: var(--zjpcy-slider-tooltip-bg);
}

.slider-container:not(.slider-container-disabled) .slider-handle:hover .slider-tooltip,
.slider-container:not(.slider-container-disabled) .slider-handle:active .slider-tooltip {
  opacity: 1;
  top: -40px;
}

/* 聚焦状态 */

.slider-handle:focus-visible {
  outline: none;
  box-shadow: var(--zjpcy-input-box-shadow-focus), var(--zjpcy-slider-handle-shadow);
}

/* 禁用状态下的工具提示 */

.slider-container-disabled .slider-tooltip {
  display: none;
}

/* ============================================
   IDP Steps Component - Modern Design System
   ============================================ */

/* ============================================
   CSS Variables - 步骤条组件专用变量
   ============================================ */

:root {
  /* 状态颜色 - 使用全局变量 */
  --zjpcy-steps-primary-color: var(--zjpcy-primary-color, #1890ff);
  --zjpcy-steps-primary-hover: var(--zjpcy-primary-hover-color, #40a9ff);
  --zjpcy-steps-success-color: var(--zjpcy-success-color, #52c41a);
  --zjpcy-steps-success-hover: #73d13d;
  --zjpcy-steps-error-color: var(--zjpcy-error-color, #f5222d);
  --zjpcy-steps-error-hover: #ff7875;
  --zjpcy-steps-wait-color: var(--zjpcy-text-color-tertiary, rgba(0, 0, 0, 0.45));
  --zjpcy-steps-text-color: var(--zjpcy-text-color, rgba(0, 0, 0, 0.85));
  --zjpcy-steps-text-secondary: var(--zjpcy-text-color-secondary, rgba(0, 0, 0, 0.65));
  --zjpcy-steps-disabled-color: var(--zjpcy-text-color-light, #bfbfbf);
  
  /* 背景与边框 */
  --zjpcy-steps-bg: var(--zjpcy-bg-color-white, #ffffff);
  --zjpcy-steps-bg-light: var(--zjpcy-bg-color-light, #f5f5f5);
  --zjpcy-steps-border-color: var(--zjpcy-border-color-extra-light, #d9d9d9);
  --zjpcy-steps-border-light: var(--zjpcy-border-color-light, #f0f0f0);
  
  /* 阴影效果 */
  --zjpcy-steps-shadow-sm: var(--zjpcy-shadow-sm, 0 2px 8px rgba(0, 0, 0, 0.15));
  --zjpcy-steps-shadow-md: var(--zjpcy-shadow-md, 0 4px 12px rgba(0, 0, 0, 0.15));
  --zjpcy-steps-shadow-primary: 0 4px 12px rgba(24, 144, 255, 0.35);
  --zjpcy-steps-shadow-success: 0 4px 12px rgba(82, 196, 26, 0.35);
  --zjpcy-steps-shadow-error: 0 4px 12px rgba(245, 34, 45, 0.35);
  
  /* 尺寸 */
  --zjpcy-steps-node-size: 32px;
  --zjpcy-steps-node-small: 24px;
  --zjpcy-steps-border-radius: var(--zjpcy-border-radius-lg, 8px);
  --zjpcy-steps-border-radius-sm: var(--zjpcy-border-radius-sm, 4px);
  
  /* 过渡动画 */
  --zjpcy-steps-transition: all var(--zjpcy-transition-duration, 0.2s) var(--zjpcy-transition-timing-function, ease-in-out);
}

/* ============================================
   Steps Container - 步骤条容器
   ============================================ */

.zjpcy-steps {
  display: flex;
  width: 100%;
  font-family: inherit;
}

/* 面板类型容器 */

.zjpcy-steps.zjpcy-steps-type-panel {
  background: linear-gradient(135deg, var(--zjpcy-steps-bg) 0%, var(--zjpcy-steps-bg-light) 100%);
  border-radius: var(--zjpcy-steps-border-radius);
  padding: 24px;
  box-shadow: var(--zjpcy-steps-shadow-sm);
  border: 1px solid var(--zjpcy-steps-border-light);
}

/* 方向布局 */

.zjpcy-steps.zjpcy-steps-direction-horizontal {
  flex-direction: row;
  align-items: flex-start;
  justify-content: space-between;
}

.zjpcy-steps.zjpcy-steps-direction-vertical {
  flex-direction: column;
}

/* ============================================
   Size Variants - 尺寸变体
   ============================================ */

.zjpcy-steps.zjpcy-steps-size-small .zjpcy-step-node {
  width: var(--zjpcy-steps-node-small);
  height: var(--zjpcy-steps-node-small);
  font-size: 12px;
  min-width: var(--zjpcy-steps-node-small);
}

.zjpcy-steps.zjpcy-steps-size-small .zjpcy-step-title {
  font-size: 12px;
}

.zjpcy-steps.zjpcy-steps-size-small .zjpcy-step-description {
  font-size: 11px;
}

/* ============================================
   Step Item - 单个步骤
   ============================================ */

.zjpcy-step {
  position: relative;
  flex: 1;
  text-align: center;
  cursor: pointer;
  transition: var(--zjpcy-steps-transition);
}

/* 面板类型步骤项 */

.zjpcy-steps.zjpcy-steps-type-panel .zjpcy-step {
  background: linear-gradient(135deg, var(--zjpcy-steps-bg) 0%, var(--zjpcy-steps-bg-light) 100%);
  border-radius: var(--zjpcy-border-radius-md, 6px);
  padding: 16px;
  margin: 0 8px;
  border: 1px solid var(--zjpcy-steps-border-light);
  transition: var(--zjpcy-steps-transition);
  box-shadow: var(--zjpcy-shadow-extra-light, 0 2px 8px rgba(0, 0, 0, 0.08));
}

.zjpcy-steps.zjpcy-steps-type-panel .zjpcy-step:hover {
  box-shadow: var(--zjpcy-steps-shadow-md);
  transform: translateY(-2px);
  border-color: var(--zjpcy-steps-primary-color);
}

.zjpcy-steps.zjpcy-steps-type-panel .zjpcy-step.zjpcy-step-process {
  border-color: var(--zjpcy-steps-primary-color);
  background: linear-gradient(135deg, rgba(24, 144, 255, 0.08) 0%, rgba(24, 144, 255, 0.02) 100%);
  box-shadow: var(--zjpcy-steps-shadow-primary);
}

.zjpcy-steps.zjpcy-steps-type-panel .zjpcy-step.zjpcy-step-finish {
  border-color: var(--zjpcy-steps-success-color);
  background: linear-gradient(135deg, rgba(82, 196, 26, 0.08) 0%, rgba(82, 196, 26, 0.02) 100%);
  box-shadow: var(--zjpcy-steps-shadow-success);
}

.zjpcy-steps.zjpcy-steps-type-panel .zjpcy-step.zjpcy-step-error {
  border-color: var(--zjpcy-steps-error-color);
  background: linear-gradient(135deg, rgba(245, 34, 45, 0.08) 0%, rgba(245, 34, 45, 0.02) 100%);
  box-shadow: var(--zjpcy-steps-shadow-error);
}

/* 禁用状态 */

.zjpcy-step.zjpcy-step-disabled {
  cursor: not-allowed;
  opacity: var(--zjpcy-opacity-disabled, 0.65);
}

/* 水平方向 */

.zjpcy-step.zjpcy-step-direction-horizontal {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  flex: 1;
  position: relative;
  padding: 0 16px;
}

/* 垂直方向 */

.zjpcy-step.zjpcy-step-direction-vertical {
  display: flex;
  align-items: flex-start;
  padding: 8px 0;
  min-height: 60px;
}

/* ============================================
   Step Head - 步骤头部
   ============================================ */

.zjpcy-step-head {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.zjpcy-step.zjpcy-step-direction-horizontal .zjpcy-step-head {
  margin-bottom: 8px;
  position: relative;
  width: 100%;
}

.zjpcy-step.zjpcy-step-direction-vertical .zjpcy-step-head {
  margin-right: 16px;
}

/* ============================================
   Step Node - 步骤节点（图标/数字）
   ============================================ */

.zjpcy-step-node {
  display: flex;
  align-items: center;
  justify-content: center;
  width: auto;
  padding: 6px;
  height: var(--zjpcy-steps-node-size);
  min-width: var(--zjpcy-steps-node-size);
  border-radius: var(--zjpcy-steps-border-radius-sm);
  font-size: 14px;
  font-weight: 600;
  border: 2px solid var(--zjpcy-steps-wait-color);
  background: linear-gradient(135deg, var(--zjpcy-steps-bg) 0%, var(--zjpcy-steps-bg-light) 100%);
  color: var(--zjpcy-steps-wait-color);
  transition: var(--zjpcy-steps-transition);
  z-index: 1;
  box-shadow: var(--zjpcy-shadow-extra-light, 0 2px 8px rgba(0, 0, 0, 0.08));
}

.zjpcy-step-node:hover {
  box-shadow: var(--zjpcy-steps-shadow-sm);
  transform: translateY(-2px);
}

/* 等待状态 */

.zjpcy-step-node.zjpcy-step-node-wait {
  border-color: var(--zjpcy-steps-wait-color);
  color: var(--zjpcy-steps-wait-color);
}

/* 进行中状态 */

.zjpcy-step-node.zjpcy-step-node-process {
  border-color: var(--zjpcy-steps-primary-color);
  background: linear-gradient(135deg, var(--zjpcy-steps-primary-color) 0%, var(--zjpcy-steps-primary-hover) 100%);
  color: var(--zjpcy-steps-bg);
  transform: scale(1.1);
  box-shadow: 0 0 0 4px rgba(24, 144, 255, 0.15), var(--zjpcy-steps-shadow-primary);
}

/* 完成状态 */

.zjpcy-step-node.zjpcy-step-node-finish {
  border-color: var(--zjpcy-steps-success-color);
  background: linear-gradient(135deg, var(--zjpcy-steps-success-color) 0%, var(--zjpcy-steps-success-hover) 100%);
  color: var(--zjpcy-steps-bg);
  transform: scale(1.05);
  box-shadow: var(--zjpcy-steps-shadow-success);
}

/* 错误状态 */

.zjpcy-step-node.zjpcy-step-node-error {
  border-color: var(--zjpcy-steps-error-color);
  background: linear-gradient(135deg, var(--zjpcy-steps-error-color) 0%, var(--zjpcy-steps-error-hover) 100%);
  color: var(--zjpcy-steps-bg);
  transform: scale(1.05);
  box-shadow: var(--zjpcy-steps-shadow-error);
}

/* ============================================
   Step Tail - 连接线
   ============================================ */

.zjpcy-step-tail {
  position: absolute;
  background-color: var(--zjpcy-steps-border-color);
  transition: var(--zjpcy-steps-transition);
  display: flex;
  align-items: center;
  justify-content: center;
}

/* 虚线样式 */

.zjpcy-step-tail-dashed {
  background: repeating-linear-gradient(
    90deg,
    var(--zjpcy-steps-border-color),
    var(--zjpcy-steps-border-color) 4px,
    transparent 4px,
    transparent 8px
  );
}

/* Tail 标题 */

.zjpcy-step-tail-title {
  position: absolute;
  top: -20px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 12px;
  color: var(--zjpcy-steps-wait-color);
  white-space: nowrap;
  background: var(--zjpcy-steps-bg);
  padding: 2px 6px;
  border-radius: var(--zjpcy-steps-border-radius-sm);
  border: 1px solid var(--zjpcy-steps-wait-color);
  z-index: 2;
  transition: var(--zjpcy-steps-transition);
  box-shadow: var(--zjpcy-shadow-extra-light, 0 2px 8px rgba(0, 0, 0, 0.08));
}

/* ============================================
   Panel Type Arrow - 面板类型箭头图标
   ============================================ */

.zjpcy-step-arrow {
  position: absolute;
  top: 50%;
  left: calc(100% + 17px);
  transform: translateY(-50%);
  width: 16px;
  height: 16px;
  color: var(--zjpcy-steps-border-color);
  transition: var(--zjpcy-steps-transition);
  display: flex;
  align-items: center;
  justify-content: center;
}

.zjpcy-step.zjpcy-step-finish .zjpcy-step-arrow {
  color: var(--zjpcy-steps-success-color);
}

.zjpcy-step.zjpcy-step-process .zjpcy-step-arrow {
  color: var(--zjpcy-steps-primary-color);
  transform: translateY(-50%) scale(1.2);
}

.zjpcy-step.zjpcy-step-error .zjpcy-step-arrow {
  color: var(--zjpcy-steps-error-color);
}

.zjpcy-step.zjpcy-step-finish .zjpcy-step-tail-title {
  color: var(--zjpcy-steps-success-color);
  border-color: var(--zjpcy-steps-success-color);
  background: linear-gradient(135deg, rgba(82, 196, 26, 0.08) 0%, var(--zjpcy-steps-bg) 100%);
}

.zjpcy-step.zjpcy-step-process .zjpcy-step-tail-title {
  color: var(--zjpcy-steps-primary-color);
  border-color: var(--zjpcy-steps-primary-color);
  background: linear-gradient(135deg, rgba(24, 144, 255, 0.08) 0%, var(--zjpcy-steps-bg) 100%);
}

.zjpcy-step.zjpcy-step-error .zjpcy-step-tail-title {
  color: var(--zjpcy-steps-error-color);
  border-color: var(--zjpcy-steps-error-color);
  background: linear-gradient(135deg, rgba(245, 34, 45, 0.08) 0%, var(--zjpcy-steps-bg) 100%);
}

/* ============================================
   Horizontal Direction - 水平方向样式
   ============================================ */

.zjpcy-step.zjpcy-step-direction-horizontal .zjpcy-step-tail {
  top: 50%;
  left: 50%;
  right: -50%;
  width: auto;
  height: 2px;
  transform: translateY(-50%);
  background-color: var(--zjpcy-steps-border-color);
  z-index: 0;
}

/* ============================================
   Vertical Direction - 垂直方向样式
   ============================================ */

.zjpcy-step.zjpcy-step-direction-vertical .zjpcy-step-tail {
  top: 100%;
  left: 50%;
  width: 2px;
  height: 100%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.zjpcy-step.zjpcy-step-direction-vertical .zjpcy-step-tail-dashed {
  background: repeating-linear-gradient(
    180deg,
    var(--zjpcy-steps-border-color),
    var(--zjpcy-steps-border-color) 4px,
    transparent 4px,
    transparent 8px
  );
}

.zjpcy-step.zjpcy-step-direction-vertical .zjpcy-step-tail-title {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%) rotate(-90deg);
  font-size: 12px;
  color: var(--zjpcy-steps-wait-color);
  white-space: nowrap;
  background: var(--zjpcy-steps-bg);
  padding: 2px 6px;
  border-radius: var(--zjpcy-steps-border-radius-sm);
  border: 1px solid var(--zjpcy-steps-wait-color);
  z-index: 2;
  transform-origin: left center;
  box-shadow: var(--zjpcy-shadow-extra-light, 0 2px 8px rgba(0, 0, 0, 0.08));
}

.zjpcy-step.zjpcy-step-direction-vertical.zjpcy-step-finish .zjpcy-step-tail-title {
  color: var(--zjpcy-steps-success-color);
  border-color: var(--zjpcy-steps-success-color);
  background: linear-gradient(135deg, rgba(82, 196, 26, 0.08) 0%, var(--zjpcy-steps-bg) 100%);
}

.zjpcy-step.zjpcy-step-direction-vertical.zjpcy-step-process .zjpcy-step-tail-title {
  color: var(--zjpcy-steps-primary-color);
  border-color: var(--zjpcy-steps-primary-color);
  background: linear-gradient(135deg, rgba(24, 144, 255, 0.08) 0%, var(--zjpcy-steps-bg) 100%);
}

.zjpcy-step.zjpcy-step-direction-vertical.zjpcy-step-error .zjpcy-step-tail-title {
  color: var(--zjpcy-steps-error-color);
  border-color: var(--zjpcy-steps-error-color);
  background: linear-gradient(135deg, rgba(245, 34, 45, 0.08) 0%, var(--zjpcy-steps-bg) 100%);
}

/* ============================================
   Tail Color States - 连接线状态颜色
   ============================================ */

.zjpcy-step.zjpcy-step-finish .zjpcy-step-tail {
  background: linear-gradient(90deg, var(--zjpcy-steps-success-color) 0%, var(--zjpcy-steps-success-hover) 100%);
  background-size: 200% 100%;
  animation: idpStepsColorFlow 1.2s ease-in-out forwards;
}

.zjpcy-step.zjpcy-step-process .zjpcy-step-tail {
  background: linear-gradient(90deg, var(--zjpcy-steps-success-color) 0%, var(--zjpcy-steps-primary-color) 50%, var(--zjpcy-steps-primary-color) 100%);
  background-size: 200% 100%;
  animation: idpStepsColorFlow 0.8s ease-in-out forwards;
}

.zjpcy-step.zjpcy-step-error .zjpcy-step-tail {
  background: linear-gradient(90deg, var(--zjpcy-steps-success-color) 0%, var(--zjpcy-steps-error-color) 50%, var(--zjpcy-steps-error-color) 100%);
  background-size: 200% 100%;
  animation: idpStepsColorFlow 0.6s ease-in-out forwards;
}

/* ============================================
   Step Content - 步骤内容
   ============================================ */

.zjpcy-step-content {
  flex: 1;
}

.zjpcy-step.zjpcy-step-direction-horizontal .zjpcy-step-content {
  max-width: 120px;
  word-wrap: break-word;
}

.zjpcy-step.zjpcy-step-direction-vertical .zjpcy-step-content {
  padding-top: 4px;
  max-width: 180px;
  min-width: 100px;
  word-wrap: break-word;
}

.zjpcy-steps.zjpcy-steps-type-panel .zjpcy-step-content {
  margin-top: 12px;
  padding: 0;
  max-width: 150px;
  word-wrap: break-word;
}

/* ============================================
   Step Title - 步骤标题
   ============================================ */

.zjpcy-step-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--zjpcy-steps-text-color);
  margin-bottom: 4px;
  transition: color var(--zjpcy-transition-duration, 0.2s) ease;
}

.zjpcy-steps.zjpcy-steps-type-panel .zjpcy-step-title {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 8px;
}

/* 标题状态颜色 */

.zjpcy-step.zjpcy-step-wait .zjpcy-step-title {
  color: var(--zjpcy-steps-wait-color);
}

.zjpcy-step.zjpcy-step-process .zjpcy-step-title {
  color: var(--zjpcy-steps-primary-color);
}

.zjpcy-step.zjpcy-step-finish .zjpcy-step-title {
  color: var(--zjpcy-steps-success-color);
}

.zjpcy-step.zjpcy-step-error .zjpcy-step-title {
  color: var(--zjpcy-steps-error-color);
}

.zjpcy-step.zjpcy-step-disabled .zjpcy-step-title {
  color: var(--zjpcy-steps-disabled-color);
}

/* ============================================
   Step Description - 步骤描述
   ============================================ */

.zjpcy-step-description {
  font-size: 12px;
  color: var(--zjpcy-steps-text-secondary);
  line-height: 1.4;
}

.zjpcy-steps.zjpcy-steps-type-panel .zjpcy-step-description {
  font-size: 14px;
  line-height: 1.5;
}

/* 描述状态颜色 */

.zjpcy-step.zjpcy-step-wait .zjpcy-step-description {
  color: var(--zjpcy-steps-wait-color);
}

.zjpcy-step.zjpcy-step-process .zjpcy-step-description {
  color: var(--zjpcy-steps-primary-color);
  opacity: 0.85;
}

.zjpcy-step.zjpcy-step-finish .zjpcy-step-description {
  color: var(--zjpcy-steps-success-color);
  opacity: 0.85;
}

.zjpcy-step.zjpcy-step-error .zjpcy-step-description {
  color: var(--zjpcy-steps-error-color);
