  align-items: stretch;
}

/* ============================================
   Layout.Header
   ============================================ */

.zjpcy-layout-header {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  padding: var(--layout-header-padding, 0 24px);
  z-index: var(--layout-header-z-index, 10);
  transition: var(--layout-header-transition, all 0.2s ease-in-out);
  box-sizing: border-box;
  /* 增强层次感：添加底部边框 */
  border-bottom: 1px solid var(--zjpcy-border-color-light, #e8e8e8);
  /* 增强层次感：更强的阴影 */
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08), 0 2px 6px rgba(0, 0, 0, 0.05);
}

.zjpcy-layout-header--light {
