/* ============================================
   遮罩层
   ============================================ */

.zjpcy-drawer-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0);
    transition: background-color 0.3s ease;
    pointer-events: none;
}

.zjpcy-drawer-overlay--visible {
    background-color: var(--zjpcy-modal-mask-bg);
    pointer-events: auto;
    backdrop-filter: blur(2px);
    -webkit-backdrop-filter: blur(2px);
}

.zjpcy-drawer-overlay--closing {
    background-color: rgba(0, 0, 0, 0);
    pointer-events: auto;
}

/* ============================================
   无遮罩层时的包装器
   ============================================ */

.zjpcy-drawer-wrapper {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;
}

.zjpcy-drawer-wrapper--visible {
    pointer-events: auto;
}

/* ============================================
   Drawer 主体
   ============================================ */

.zjpcy-drawer {
    position: absolute;
    background: linear-gradient(180deg, var(--zjpcy-bg-color-white) 0%, var(--zjpcy-bg-color-white) 100%);
    box-shadow: var(--zjpcy-shadow-lg);
    display: flex;
    flex-direction: column;
    transition: transform 0.3s cubic-bezier(0.23, 1, 0.32, 1);
    min-width: 0;
    min-height: 0;
}

/* ============================================
   左侧抽屉
   ============================================ */

.zjpcy-drawer--left {
    left: 0;
    top: 0;
    bottom: 0;
    transform: translateX(-100%);
}

/* 使用后代选择器避免多类选择器 */

.zjpcy-drawer-wrapper--visible .zjpcy-drawer--left,
.zjpcy-drawer-overlay--visible .zjpcy-drawer--left {
    transform: translateX(0);
}

.zjpcy-drawer-wrapper--closing .zjpcy-drawer--left,
.zjpcy-drawer-overlay--closing .zjpcy-drawer--left {
    transform: translateX(-100%);
}

/* ============================================
   右侧抽屉
   ============================================ */

.zjpcy-drawer--right {
    right: 0;
    top: 0;
    bottom: 0;
    transform: translateX(100%);
}

/* 使用后代选择器避免多类选择器 */

.zjpcy-drawer-wrapper--visible .zjpcy-drawer--right,
.zjpcy-drawer-overlay--visible .zjpcy-drawer--right {
    transform: translateX(0);
}

.zjpcy-drawer-wrapper--closing .zjpcy-drawer--right,
.zjpcy-drawer-overlay--closing .zjpcy-drawer--right {
    transform: translateX(100%);
}

/* ============================================
   顶部抽屉
   ============================================ */

.zjpcy-drawer--top {
    top: 0;
    left: 0;
    right: 0;
    transform: translateY(-100%);
}

/* 使用后代选择器避免多类选择器 */

.zjpcy-drawer-wrapper--visible .zjpcy-drawer--top,
.zjpcy-drawer-overlay--visible .zjpcy-drawer--top {
    transform: translateY(0);
}

.zjpcy-drawer-wrapper--closing .zjpcy-drawer--top,
.zjpcy-drawer-overlay--closing .zjpcy-drawer--top {
    transform: translateY(-100%);
}

/* ============================================
   底部抽屉
   ============================================ */

.zjpcy-drawer--bottom {
    bottom: 0;
    left: 0;
    right: 0;
    transform: translateY(100%);
}

/* 使用后代选择器避免多类选择器 */

.zjpcy-drawer-wrapper--visible .zjpcy-drawer--bottom,
.zjpcy-drawer-overlay--visible .zjpcy-drawer--bottom {
    transform: translateY(0);
}

.zjpcy-drawer-wrapper--closing .zjpcy-drawer--bottom,
.zjpcy-drawer-overlay--closing .zjpcy-drawer--bottom {
    transform: translateY(100%);
}

/* ============================================
   无遮罩层时的定位
   ============================================ */

.zjpcy-drawer-wrapper--no-mask .zjpcy-drawer--left,
.zjpcy-drawer-wrapper--no-mask .zjpcy-drawer--right {
    position: fixed;
    top: 0;
    bottom: 0;
}

.zjpcy-drawer-wrapper--no-mask .zjpcy-drawer--top,
.zjpcy-drawer-wrapper--no-mask .zjpcy-drawer--bottom {
    position: fixed;
    left: 0;
    right: 0;
}

/* ============================================
   头部样式
   ============================================ */

.zjpcy-drawer-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 20px;
    border-bottom: 1px solid var(--zjpcy-border-color-light);
    flex-shrink: 0;
    background: linear-gradient(180deg, var(--zjpcy-bg-color-white) 0%, var(--zjpcy-bg-color) 100%);
}

.zjpcy-drawer-header__title {
    font-size: 16px;
    font-weight: 600;
    color: var(--zjpcy-text-color);
    line-height: 1.5;
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    letter-spacing: 0.3px;
}

.zjpcy-drawer-header__close {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    padding: 0;
    margin: 0;
    margin-left: 12px;
    border: none;
    background: transparent;
    cursor: pointer;
    border-radius: var(--zjpcy-border-radius-md);
    transition: all var(--zjpcy-transition-duration) ease;
    color: var(--zjpcy-text-color-tertiary);
}

.zjpcy-drawer-header__close:hover {
    background: rgba(0, 0, 0, 0.06);
    color: var(--zjpcy-error-color);
    transform: rotate(90deg);
}

/* ============================================
   内容区域
   ============================================ */

.zjpcy-drawer-content {
    flex: 1;
    overflow: auto;
    padding: 24px;
    box-sizing: border-box;
    min-width: 0;
    min-height: 0;
    width: 100%;
    background: var(--zjpcy-bg-color-white);
}

/* 确保内容区域内的所有元素使用 border-box */

.zjpcy-drawer-content *,
.zjpcy-drawer-content *::before,
.zjpcy-drawer-content *::after {
    box-sizing: border-box;
}

/* ============================================
   页脚
   ============================================ */

.zjpcy-drawer-footer {
    padding: 16px 24px;
    border-top: 1px solid var(--zjpcy-border-color-light);
    flex-shrink: 0;
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    background: linear-gradient(180deg, var(--zjpcy-bg-color) 0%, var(--zjpcy-bg-color-light) 100%);
}

/* ============================================
   加载状态
   ============================================ */

.zjpcy-drawer-loading {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(255, 255, 255, 0.6);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 10;
    backdrop-filter: blur(2px);
    -webkit-backdrop-filter: blur(2px);
}

.zjpcy-drawer-loading-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
}

.zjpcy-drawer-loading-spinner {
    width: 32px;
    height: 32px;
}

.zjpcy-drawer-loading-icon {
    width: 100%;
    height: 100%;
    animation: zjpcy-drawer-loading-rotate 1s linear infinite;
}

.zjpcy-drawer-loading-track {
    stroke: var(--zjpcy-border-color-light, rgba(0, 0, 0, 0.1));
}

.zjpcy-drawer-loading-indicator {
    stroke: var(--zjpcy-primary-color, #1890ff);
    stroke-dasharray: 60;
    stroke-dashoffset: 40;
    stroke-linecap: round;
    transform-origin: center;
}

.zjpcy-drawer-loading-text {
    font-size: 14px;
    color: var(--zjpcy-text-color-secondary, rgba(0, 0, 0, 0.65));
    text-align: center;
}

@keyframes zjpcy-drawer-loading-rotate {
    from {
        transform: rotate(0deg);
    }
    to {
        transform: rotate(360deg);
    }
}

/* ============================================
   滚动条样式
   ============================================ */

.zjpcy-drawer-content::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

.zjpcy-drawer-content::-webkit-scrollbar-track {
    background: var(--zjpcy-bg-color);
    border-radius: var(--zjpcy-border-radius-sm);
}

.zjpcy-drawer-content::-webkit-scrollbar-thumb {
    background: var(--zjpcy-border-color-extra-light);
    border-radius: var(--zjpcy-border-radius-sm);
    border: 2px solid var(--zjpcy-bg-color);
    -webkit-transition: background var(--zjpcy-transition-duration) ease;
    transition: background var(--zjpcy-transition-duration) ease;
}

.zjpcy-drawer-content::-webkit-scrollbar-thumb:hover {
    background: var(--zjpcy-text-color-light);
}

/* ============================================
   拖拽手柄
   ============================================ */

.zjpcy-drawer-resize-handle {
    position: absolute;
    background: transparent;
    transition: all var(--zjpcy-transition-duration) ease;
    z-index: 1;
}

/* 左侧抽屉 - 手柄在右边 */

.zjpcy-drawer-resize-handle--right {
    right: 0;
    top: 0;
    bottom: 0;
    width: 8px;
    cursor: col-resize;
}

/* 右侧抽屉 - 手柄在左边 */

.zjpcy-drawer-resize-handle--left {
    left: 0;
    top: 0;
    bottom: 0;
    width: 8px;
    cursor: col-resize;
}

/* 顶部抽屉 - 手柄在底部 */

.zjpcy-drawer-resize-handle--bottom {
    left: 0;
    right: 0;
    bottom: 0;
    height: 8px;
    cursor: row-resize;
}

/* 底部抽屉 - 手柄在顶部 */

.zjpcy-drawer-resize-handle--top {
    left: 0;
    right: 0;
    top: 0;
    height: 8px;
    cursor: row-resize;
}

/* 拖拽手柄悬停效果 */

.zjpcy-drawer-resize-handle:hover {
    background: rgba(24, 144, 255, 0.1);
}

.zjpcy-drawer-resize-handle:active {
    background: rgba(24, 144, 255, 0.2);
}

/* ============================================
   拖拽中状态
   ============================================ */

.zjpcy-drawer-overlay--resizing {
    cursor: inherit;
}

.zjpcy-drawer--resizing {
    transition: none !important;
    will-change: width, height;
    -webkit-user-select: none;
       -moz-user-select: none;
            user-select: none;
}

/* 拖拽时禁用全局文本选择 */

.zjpcy-drawer--resizing,
.zjpcy-drawer--resizing * {
    user-select: none !important;
    -webkit-user-select: none !important;
    -moz-user-select: none !important;
    -ms-user-select: none !important;
}

/* 无遮罩层时的拖拽手柄定位 */

.zjpcy-drawer-wrapper--no-mask .zjpcy-drawer-resize-handle--left,
.zjpcy-drawer-wrapper--no-mask .zjpcy-drawer-resize-handle--right {
    position: fixed;
}

.zjpcy-drawer-wrapper--no-mask .zjpcy-drawer-resize-handle--top,
.zjpcy-drawer-wrapper--no-mask .zjpcy-drawer-resize-handle--bottom {
    position: fixed;
}

.zjpcy-tag {
    display: inline-flex;
    align-items: center;
    box-sizing: border-box;
    font-size: var(--tag-font-size, 14px);
    line-height: 1.5;
    border-radius: var(--tag-border-radius, 4px);
    border: 1px solid transparent;
    white-space: nowrap;
    transition: all 0.2s ease;
    background-color: var(--tag-bg-color, #f5f5f5);
    color: var(--tag-text-color, #333);
}

/* 尺寸样式 */

.zjpcy-tag--small {
    height: 20px;
    padding: 0 6px;
    font-size: 12px;
}

.zjpcy-tag--small .zjpcy-tag__icon {
    margin-right: 2px;
    font-size: 10px;
}

.zjpcy-tag--small .zjpcy-tag__close {
    margin-left: 2px;
    font-size: 10px;
}

.zjpcy-tag--medium {
    height: 24px;
    padding: 0 8px;
    font-size: 13px;
}

.zjpcy-tag--medium .zjpcy-tag__icon {
    margin-right: 4px;
    font-size: 12px;
}

.zjpcy-tag--medium .zjpcy-tag__close {
    margin-left: 4px;
    font-size: 12px;
}

.zjpcy-tag--large {
    height: 28px;
    padding: 0 12px;
    font-size: 14px;
}

.zjpcy-tag--large .zjpcy-tag__icon {
    margin-right: 6px;
    font-size: 14px;
}

.zjpcy-tag--large .zjpcy-tag__close {
    margin-left: 6px;
    font-size: 14px;
}

/* 内容样式 */

.zjpcy-tag__content {
    display: inline-flex;
    align-items: center;
}

/* 图标样式 */

.zjpcy-tag__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.zjpcy-tag__icon svg {
    width: 1em;
    height: 1em;
}

/* 关闭按钮样式 */

.zjpcy-tag__close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: inherit;
    opacity: 0.6;
    transition: opacity 0.2s ease;
    margin-left: 4px;
}

.zjpcy-tag__close:hover {
    opacity: 1;
}

.zjpcy-tag__close svg {
    width: 1em;
    height: 1em;
}

/* 可点击样式 */

.zjpcy-tag--clickable {
    cursor: pointer;
}

.zjpcy-tag--clickable:hover {
    opacity: 0.85;
}

/* 可关闭标签的额外样式 */

.zjpcy-tag--closable {
    padding-right: 4px;
}

/* ============================================
   IDP Design System - 全局 CSS 变量
   ============================================ */

/* ============================================
   ANTI-FOUC: SSR 闪烁防护
   确保服务端渲染期间有正确的默认样式
   ============================================ */

/* 基础防护：确保 HTML 和 body 默认使用亮色背景 */

html, body {
  background-color: #ffffff;
}

/* 主题颜色变量定义 */

:root {
  /* 主色调 - 主要用于强调和突出显示 */
  --zjpcy-primary-color: #1890ff; /* 主色调基础色 - 用于按钮、链接等主要交互元素 */
  --zjpcy-primary-hover-color: #40a9ff; /* 主色调悬停色 - 用于鼠标悬停状态 */
  --zjpcy-primary-light-color: rgba(24, 100, 240, 0.1); /* 主色调浅色 - 用于多选选中背景等 */
  
  /* 辅助色 - 用于不同状态和场景 */
  --zjpcy-success-color: #52c41a; /* 成功色 - 用于成功状态、确认操作等 */
  --zjpcy-warning-color: #faad14; /* 警告色 - 用于警告提示、需要注意的操作等 */
  --zjpcy-error-color: #f5222d; /* 错误色 - 用于错误提示、危险操作等 */
  --zjpcy-info-color: #1890ff; /* 信息色 - 用于普通信息提示 */
  --zjpcy-secondary-color: #fff; /* 次要色 - 用于次要按钮、辅助文本等 */
  --zjpcy-secondary-border-color: #d9d9d9; /* 次要边框色 - 用于次要按钮、辅助文本等 */
  --zjpcy-primary-secondary-border-color: #1890ff; /* 主要次要边框色 - 用于主要次要按钮、辅助文本等 */

  /* 中性色 - 用于文本、边框、背景等基础元素 */
  --zjpcy-text-color: rgba(0, 0, 0, 0.85); /* 主要文本色 - 用于正文、标题等 */
  --zjpcy-text-color-secondary: rgba(0, 0, 0, 0.65); /* 次要文本色 - 用于副标题、辅助说明等 */
  --zjpcy-text-color-tertiary: rgba(0, 0, 0, 0.45); /*  tertiary文本色 - 用于次要信息、提示文字等 */
  --zjpcy-text-color-light: #bfbfbf; /* 浅色文本 - 用于禁用状态、占位符等 */
  --zjpcy-border-color: #e8e8e8; /* 基础边框色 - 用于容器、分割线等 */
  --zjpcy-border-color-light: #f0f0f0; /* 浅色边框 - 用于次要分割、卡片边框等 */
  --zjpcy-border-color-extra-light: #d9d9d9; /* 超浅色边框 - 用于输入框、表格边框等 */
  --zjpcy-bg-color: #fafafa; /* 基础背景色 - 用于页面背景、容器背景等 */
  --zjpcy-bg-color-light: #f5f5f5; /* 浅色背景 - 用于卡片、组件背景等 */
  --zjpcy-bg-color-white: #fff; /* 白色背景 - 用于主要内容区域、弹窗等 */
  
  /* 阴影效果 - 用于组件的悬浮和层次感 */
  --zjpcy-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.15); /* 小阴影 - 用于轻微悬浮效果 */
  --zjpcy-shadow-md: 0 4px 12px rgba(0, 0, 0, 0.15); /* 中阴影 - 用于卡片、弹窗等 */
  --zjpcy-shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.15); /* 大阴影 - 用于模态框、下拉菜单等 */
  --zjpcy-shadow-extra-light: 0 2px 8px rgba(0, 0, 0, 0.08); /* 超浅阴影 - 用于轻微凸起效果 */
  
  /* 圆角 - 用于组件的边角处理 */
  --zjpcy-border-radius-sm: 2px; /* 小圆角 - 用于按钮、输入框等小组件 */
  --zjpcy-border-radius-md: 6px; /* 中圆角 - 用于卡片、弹窗等中等组件 */
  --zjpcy-border-radius-lg: 4px; /* 大圆角 - 用于模态框、特殊容器等 */
  
  /* 动画 - 用于过渡和动效 */
  --zjpcy-transition-duration: 0.2s; /* 过渡动画持续时间 - 控制动画快慢 */
  --zjpcy-transition-timing-function: ease-in-out; /* 过渡动画缓动函数 - 控制动画节奏 */
  
  /* 透明度 - 用于元素的显示状态 */
  --zjpcy-opacity-disabled: 0.65; /* 禁用状态透明度 - 用于禁用的按钮、输入框等 */
  
  /* z-index - 用于控制元素的堆叠顺序 */
  --zjpcy-z-index-modal: 1000; /* 模态框层级 - 确保模态框在最上层 */
  --zjpcy-z-index-message: 1050; /* 消息提示层级 - 确保消息提示在模态框之上 */
  --zjpcy-z-index-marquee-fixed: 99999; /* 跑马灯固定层级 - 确保跑马灯始终在最顶层 */
  
  /* Button 组件 - 按钮相关样式变量 */
  --zjpcy-button-primary-bg: var(--zjpcy-primary-color); /* 主要按钮背景色 */
  --zjpcy-button-primary-border: var(--zjpcy-primary-color); /* 主要按钮边框色 */
  --zjpcy-button-primary-hover-bg: var(--zjpcy-primary-hover-color); /* 主要按钮悬停背景色 */
  --zjpcy-button-primary-hover-border: var(--zjpcy-primary-hover-color); /* 主要按钮悬停边框色 */
  --zjpcy-button-primary-active-shadow: 0 4px 8px rgba(24, 144, 255, 0.4); /* 主要按钮激活阴影 */
  
  --zjpcy-button-secondary-bg: var(--zjpcy-secondary-color); /* 次要按钮背景色 */
