    color: var(--zjpcy-input-suffix-color);
    font-size: 14px;
}

/* ============================================
   范围选择器后缀区域
   ============================================ */

.zjpcy-datepicker-range-picker-suffix {
    display: flex;
    align-items: center;
    margin-left: 8px;
    color: var(--zjpcy-input-suffix-color);
    transition: all var(--zjpcy-transition-duration) ease;
    position: relative;
    width: 16px;
    height: 16px;
}

/* ============================================
   清除按钮
   ============================================ */

.zjpcy-datepicker-range-picker-clear {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    color: var(--zjpcy-text-color-tertiary);
    cursor: pointer;
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.06);
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(0.8) rotate(-45deg);
    transition: all var(--zjpcy-transition-duration) ease;
    opacity: 0;
    visibility: hidden;
    z-index: 2;
}

/* 悬停触发器时显示清除按钮 */

.zjpcy-datepicker-range-picker-trigger:hover .zjpcy-datepicker-range-picker-clear {
    opacity: 1;
    visibility: visible;
    transform: translate(-50%, -50%) scale(1) rotate(0deg);
}

.zjpcy-datepicker-range-picker-clear:hover {
    background: rgba(0, 0, 0, 0.12);
    color: var(--zjpcy-text-color-secondary);
    transform: translate(-50%, -50%) scale(1.1) !important;
}

/* ============================================
   日历图标
   ============================================ */

.zjpcy-datepicker-range-picker-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    transition: all var(--zjpcy-transition-duration) ease;
    opacity: 1;
    visibility: visible;
    z-index: 1;
    width: 16px;
    height: 16px;
}

/* 当有清除按钮且悬停时，隐藏日历图标 */

.zjpcy-datepicker-range-picker-trigger:hover .zjpcy-datepicker-range-picker-icon--has-clear {
    opacity: 0;
    visibility: hidden;
}

/* ============================================
   范围选择器下拉面板
   ============================================ */

.zjpcy-datepicker-range-dropdown {
    background: linear-gradient(180deg, var(--zjpcy-bg-color-white) 0%, var(--zjpcy-bg-color-white) 100%);
    border-radius: var(--zjpcy-border-radius-lg);
    box-shadow: var(--zjpcy-shadow-lg);
    overflow: hidden;
    animation: datePickerSlideIn 0.2s var(--zjpcy-transition-timing-function);
}

/* ============================================
   双面板容器
   ============================================ */

.zjpcy-datepicker-range-panels {
    display: flex;
    gap: 16px;
    padding: 16px;
}

/* ============================================
   日历面板
   ============================================ */

.zjpcy-datepicker-range-calendar {
    flex: 1;
    min-width: 252px;
}

/* ============================================
   日历头部
   ============================================ */

.zjpcy-datepicker-range-calendar-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 0;
    margin-bottom: 8px;
    border-bottom: 1px solid var(--zjpcy-border-color-light);
}

/* 日历头部左侧 */

.zjpcy-datepicker-range-header-left {
    display: flex;
    align-items: center;
    gap: 4px;
}

/* 日历头部中间 */

.zjpcy-datepicker-range-header-center {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 14px;
    font-weight: 500;
    color: var(--zjpcy-text-color);
}

/* 日历头部标签 */

.zjpcy-datepicker-range-header-label {
    font-size: 12px;
    color: var(--zjpcy-text-color-tertiary);
    margin-left: 8px;
}

/* 日历头部右侧 */

.zjpcy-datepicker-range-header-right {
    display: flex;
    align-items: center;
    gap: 4px;
}

/* ============================================
   日历头部按钮
   ============================================ */

.zjpcy-datepicker-range-header-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border: none;
    background: transparent;
    cursor: pointer;
    border-radius: var(--zjpcy-border-radius-sm);
    color: var(--zjpcy-text-color-secondary);
    transition: all var(--zjpcy-transition-duration) ease;
}

.zjpcy-datepicker-range-header-btn:hover:not(:disabled) {
    background: var(--zjpcy-bg-color-white);
    color: var(--zjpcy-primary-color);
    box-shadow: var(--zjpcy-shadow-extra-light);
}

.zjpcy-datepicker-range-header-btn:disabled {
    cursor: not-allowed;
    opacity: var(--zjpcy-opacity-disabled);
}

/* ============================================
   日历内容区域
   ============================================ */

.zjpcy-datepicker-range-calendar-body {
    padding: 8px 0;
}

/* ============================================
   星期标题行
   ============================================ */

.zjpcy-datepicker-range-week-header {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 0;
    margin-bottom: 4px;
}

/* 星期标题 */

.zjpcy-datepicker-range-week-day {
    text-align: center;
    font-size: 12px;
    color: var(--zjpcy-text-color-tertiary);
    padding: 4px 0;
    font-weight: 500;
}

/* ============================================
   日期网格
   ============================================ */

.zjpcy-datepicker-range-date-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 4px;
}

/* ============================================
   日期单元格
   ============================================ */

.zjpcy-datepicker-range-date-cell {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 28px;
    font-size: 13px;
    cursor: pointer;
    border-radius: var(--zjpcy-border-radius-sm);
    transition: all var(--zjpcy-transition-duration) ease;
    color: var(--zjpcy-text-color);
    animation: datePickerCellScale 0.15s ease-out;
}

.zjpcy-datepicker-range-date-cell:hover:not(.zjpcy-datepicker-range-date-cell--disabled):not(.zjpcy-datepicker-range-date-cell--selected):not(.zjpcy-datepicker-range-date-cell--in-range) {
    background: var(--zjpcy-bg-color-light);
    box-shadow: var(--zjpcy-shadow-extra-light);
}

.zjpcy-datepicker-range-date-cell--selected {
    background: linear-gradient(135deg, var(--zjpcy-primary-color) 0%, var(--zjpcy-primary-hover-color) 100%);
    color: #fff;
    font-weight: 500;
    box-shadow: 0 2px 6px rgba(24, 144, 255, 0.35);
}

.zjpcy-datepicker-range-date-cell--today:not(.zjpcy-datepicker-range-date-cell--selected):not(.zjpcy-datepicker-range-date-cell--in-range) {
    color: var(--zjpcy-primary-color);
    border: 1.5px solid var(--zjpcy-primary-color);
    font-weight: 500;
}

.zjpcy-datepicker-range-date-cell--disabled {
    cursor: not-allowed;
    color: var(--zjpcy-text-color-light);
    background: transparent;
    opacity: var(--zjpcy-opacity-disabled);
}

.zjpcy-datepicker-range-date-cell--other-month {
    color: var(--zjpcy-text-color-light);
}

/* ============================================
   范围内日期
   ============================================ */

.zjpcy-datepicker-range-date-cell--in-range {
    background: rgba(24, 144, 255, 0.1);
    border-radius: 0;
}

.zjpcy-datepicker-range-date-cell--in-range:hover {
    background: rgba(24, 144, 255, 0.2);
}

/* ============================================
   范围起点和终点
   ============================================ */

.zjpcy-datepicker-range-date-cell--range-start {
    background: linear-gradient(135deg, var(--zjpcy-primary-color) 0%, var(--zjpcy-primary-hover-color) 100%);
    color: #fff;
    font-weight: 500;
    border-radius: var(--zjpcy-border-radius-sm) 0 0 var(--zjpcy-border-radius-sm);
    box-shadow: 0 2px 6px rgba(24, 144, 255, 0.35);
}

.zjpcy-datepicker-range-date-cell--range-end {
    background: linear-gradient(135deg, var(--zjpcy-primary-color) 0%, var(--zjpcy-primary-hover-color) 100%);
    color: #fff;
    font-weight: 500;
    border-radius: 0 var(--zjpcy-border-radius-sm) var(--zjpcy-border-radius-sm) 0;
    box-shadow: 0 2px 6px rgba(24, 144, 255, 0.35);
}

/* ============================================
   日历底部
   ============================================ */

.zjpcy-datepicker-range-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px 16px;
    border-top: 1px solid var(--zjpcy-border-color-light);
    gap: 8px;
    background: linear-gradient(135deg, var(--zjpcy-bg-color) 0%, var(--zjpcy-bg-color-light) 100%);
}

/* ============================================
   日历底部占位
   ============================================ */

.zjpcy-datepicker-range-footer-spacer {
    flex: 1;
}

/* ============================================
   日历底部按钮组
   ============================================ */

.zjpcy-datepicker-range-footer-actions {
    display: flex;
    align-items: center;
    gap: 8px;
}

/* ============================================
   底部按钮
   ============================================ */

.zjpcy-datepicker-range-btn {
    padding: 5px 14px;
    font-size: 13px;
    border-radius: var(--zjpcy-border-radius-sm);
    cursor: pointer;
    transition: all var(--zjpcy-transition-duration) ease;
    border: 1px solid var(--zjpcy-border-color-extra-light);
    background: linear-gradient(135deg, var(--zjpcy-bg-color-white) 0%, var(--zjpcy-bg-color-light) 100%);
    color: var(--zjpcy-text-color);
    font-weight: 500;
    box-shadow: var(--zjpcy-shadow-extra-light);
}

.zjpcy-datepicker-range-btn:hover:not(:disabled) {
    border-color: var(--zjpcy-primary-color);
    color: var(--zjpcy-primary-color);
    box-shadow: var(--zjpcy-shadow-sm);
}

.zjpcy-datepicker-range-btn--primary {
    border-color: var(--zjpcy-primary-color);
    background: linear-gradient(135deg, var(--zjpcy-primary-color) 0%, var(--zjpcy-primary-hover-color) 100%);
    color: #fff;
    box-shadow: 0 2px 8px rgba(24, 144, 255, 0.35);
}

.zjpcy-datepicker-range-btn--primary:hover:not(:disabled) {
    background: linear-gradient(135deg, var(--zjpcy-primary-hover-color) 0%, #69c0ff 100%);
    border-color: var(--zjpcy-primary-hover-color);
    box-shadow: 0 4px 12px rgba(24, 144, 255, 0.45);
}

.zjpcy-datepicker-range-btn:disabled {
    cursor: not-allowed;
    opacity: var(--zjpcy-opacity-disabled);
}

/* ============================================
   IDP Tree Component - Modern Design System
   ============================================ */

/* 基础树形结构 */

.zjpcy-tree {
  box-sizing: border-box;
  margin: 0;
  padding: var(--zjpcy-spacing-sm);
  font-size: 14px;
  line-height: 1.5715;
  list-style: none;
  color: var(--zjpcy-text-color);
  background: var(--zjpcy-bg-color-white);
  border-radius: var(--zjpcy-border-radius-lg);
}

/* ============================================
   树节点样式
   ============================================ */

.zjpcy-tree-treenode {
  position: relative;
  padding: 2px 0;
  margin: 0;
  list-style: none;
  outline: none;
  white-space: nowrap;
  transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}

/* 省略模式：启用 flex 布局 */

.zjpcy-tree-treenode-ellipsis {
  display: flex;
  align-items: center;
}

.zjpcy-tree-treenode:focus > .zjpcy-tree-node-content-wrapper {
  outline: none;
}

/* ============================================
   禁用状态
   ============================================ */

.zjpcy-tree-treenode-disabled {
  cursor: not-allowed;
  opacity: var(--zjpcy-opacity-disabled);
}

.zjpcy-tree-treenode-disabled .zjpcy-tree-node-content-wrapper {
  cursor: not-allowed;
  color: var(--zjpcy-text-color-light);
  background: transparent !important;
}

.zjpcy-tree-treenode-disabled .zjpcy-tree-icon {
  color: var(--zjpcy-text-color-light);
}

/* ============================================
   节点内容包装器
   ============================================ */

.zjpcy-tree-node-content-wrapper {
  display: flex;
  align-items: center;
  padding: 4px var(--zjpcy-spacing-sm);
  border-radius: var(--zjpcy-border-radius-md);
  cursor: pointer;
  transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
  -webkit-user-select: none;
     -moz-user-select: none;
          user-select: none;
  position: relative;
  overflow: hidden;
  flex: 1;
  min-width: 0;
  max-width: 100%;
}

.zjpcy-tree-node-content-wrapper:hover {
  background: linear-gradient(135deg, var(--zjpcy-bg-color-light) 0%, var(--zjpcy-bg-color) 100%);
}

.zjpcy-tree-node-content-wrapper .zjpcy-tree-title {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ============================================
   选中状态
   ============================================ */

.zjpcy-tree-node-selected .zjpcy-tree-node-content-wrapper {
  background: linear-gradient(135deg, var(--zjpcy-primary-light-color) 0%, rgba(24, 144, 255, 0.08) 100%);
  color: var(--zjpcy-primary-color);
  font-weight: 500;
  box-shadow: var(--zjpcy-shadow-extra-light);
}

.zjpcy-tree-node-selected .zjpcy-tree-node-content-wrapper:hover {
  background: linear-gradient(135deg, rgba(24, 144, 255, 0.15) 0%, rgba(24, 144, 255, 0.1) 100%);
}

.zjpcy-tree-node-selected .zjpcy-tree-icon {
  color: var(--zjpcy-primary-color);
}

/* ============================================
   缩进样式
   ============================================ */

.zjpcy-tree-indent {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 24px;
  flex-shrink: 0;
}

/* 移除最后一级的缩进线 */

.zjpcy-tree-treenode:last-child > .zjpcy-tree-indent::before {
  height: 50%;
}

/* ============================================
   切换器样式（展开/收起）
   ============================================ */

.zjpcy-tree-switcher {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  margin: 0 2px;
  padding: 0;
  vertical-align: middle;
  border: 0 none;
  background: transparent;
  cursor: pointer;
  outline: none;
  border-radius: var(--zjpcy-border-radius-sm);
  transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
  color: var(--zjpcy-text-color-tertiary);
}

.zjpcy-tree-switcher:hover {
  background: linear-gradient(135deg, var(--zjpcy-bg-color-light) 0%, var(--zjpcy-bg-color) 100%);
  color: var(--zjpcy-text-color);
}

.zjpcy-tree-switcher-close {
  transform: rotate(0deg);
}

.zjpcy-tree-switcher-open {
  transform: rotate(90deg);
}

.zjpcy-tree-switcher svg {
  transition: transform var(--zjpcy-transition-duration) ease;
}

.zjpcy-tree-switcher-noline_close::after,
.zjpcy-tree-switcher-noline_open::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border: 4px solid transparent;
  border-left-color: currentColor;
  transform: translate(-3px, -50%);
}

/* ============================================
   复选框样式 - 统一 Checkbox 组件风格
   ============================================ */

.zjpcy-tree-checkbox {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  margin: 0 8px 0 0;
  padding: 0;
  vertical-align: middle;
  border: 2px solid var(--zjpcy-border-color-extra-light);
  border-radius: var(--zjpcy-border-radius-sm);
  background: var(--zjpcy-bg-color-white);
  cursor: pointer;
  transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
  box-sizing: border-box;
  flex-shrink: 0;
}

.zjpcy-tree-checkbox:hover {
  border-color: var(--zjpcy-primary-color);
  box-shadow: var(--zjpcy-input-box-shadow-hover);
}

.zjpcy-tree-checkbox-checked {
  background: linear-gradient(135deg, var(--zjpcy-primary-color) 0%, var(--zjpcy-primary-hover-color) 100%);
  border-color: var(--zjpcy-primary-color);
}

.zjpcy-tree-checkbox-checked::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 5px;
  width: 4px;
  height: 8px;
  border: solid white;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

.zjpcy-tree-checkbox-indeterminate {
  background: linear-gradient(135deg, var(--zjpcy-primary-color) 0%, var(--zjpcy-primary-hover-color) 100%);
  border-color: var(--zjpcy-primary-color);
}

.zjpcy-tree-checkbox-indeterminate::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 8px;
  height: 2px;
  background-color: white;
}

.zjpcy-tree-checkbox-disabled {
  cursor: not-allowed;
  opacity: var(--zjpcy-opacity-disabled);
  background: var(--zjpcy-bg-color-light);
}

.zjpcy-tree-checkbox-disabled:hover {
  border-color: var(--zjpcy-border-color-extra-light);
}

.zjpcy-tree-checkbox-disabled-checked {
  background: var(--zjpcy-bg-color-light);
  border-color: var(--zjpcy-border-color-extra-light);
}

.zjpcy-tree-checkbox-disabled-checked::after {
  border-color: var(--zjpcy-text-color-light);
}

.zjpcy-tree-checkbox-disabled-indeterminate {
  background: var(--zjpcy-bg-color-light);
  border-color: var(--zjpcy-border-color-extra-light);
}

.zjpcy-tree-checkbox-disabled-indeterminate::after {
  background-color: var(--zjpcy-text-color-light);
}

/* ============================================
   图标样式
   ============================================ */

.zjpcy-tree-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  margin: 0 6px 0 0;
  font-size: 16px;
  vertical-align: middle;
  color: var(--zjpcy-text-color-tertiary);
  transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
}

.zjpcy-tree-icon svg {
  width: 16px;
  height: 16px;
}

/* ============================================
   标题样式
   ============================================ */

.zjpcy-tree-title {
  padding: 0 4px;
  transition: all var(--zjpcy-transition-duration) var(--zjpcy-transition-timing-function);
}

/* ============================================
   子树样式 - 与 Menu 组件动画保持一致
   ============================================ */

.zjpcy-tree-child-tree {
  overflow: hidden;
  position: relative;
  width: 100%;
  flex-basis: 100%;
  flex-shrink: 0;
  order: 99;
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transition: grid-template-rows 0.3s ease-out, opacity 0.2s ease-out;
  will-change: grid-template-rows, opacity;
}

.zjpcy-tree-child-tree-expand {
  overflow: visible;
  grid-template-rows: 1fr;
  opacity: 1;
}

.zjpcy-tree-child-tree > div {
  overflow: hidden;
}

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode {
  opacity: 0;
  transform: translateX(-8px);
  transition: opacity 0.2s ease-out, transform 0.2s ease-out;
}

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode {
  opacity: 1;
  transform: translateX(0);
}

/* 子树节点依次动画 */

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode:nth-child(1) { transition-delay: 0.01s, 0.01s; }

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode:nth-child(2) { transition-delay: 0.02s, 0.02s; }

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode:nth-child(3) { transition-delay: 0.03s, 0.03s; }

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode:nth-child(4) { transition-delay: 0.04s, 0.04s; }

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode:nth-child(5) { transition-delay: 0.05s, 0.05s; }

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode:nth-child(6) { transition-delay: 0.06s, 0.06s; }

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode:nth-child(7) { transition-delay: 0.07s, 0.07s; }

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode:nth-child(8) { transition-delay: 0.08s, 0.08s; }

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode:nth-child(9) { transition-delay: 0.09s, 0.09s; }

.zjpcy-tree-child-tree-expand > div > .zjpcy-tree-treenode:nth-child(10) { transition-delay: 0.10s, 0.10s; }

/* ============================================
   连接线样式
   ============================================ */

.zjpcy-tree-show-line .zjpcy-tree-treenode {
  position: relative;
}

.zjpcy-tree-show-line .zjpcy-tree-child-tree::before {
  content: '';
  position: absolute;
  top: 0;
  left: 10px;
  bottom: 14px;
  width: 1px;
  background: linear-gradient(to bottom, var(--zjpcy-border-color), transparent);
}

.zjpcy-tree-line-point {
  position: absolute;
  left: -14px;
  top: 50%;
  width: 8px;
  height: 1px;
  background-color: var(--zjpcy-border-color);
  transform: translateY(-50%);
}

/* ============================================
   加载中样式
   ============================================ */

.zjpcy-tree-loading {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
}

.zjpcy-tree-loading-icon {
  animation: zjpcy-tree-spin 1s linear infinite;
  color: var(--zjpcy-primary-color);
}

@keyframes zjpcy-tree-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* ============================================
   拖拽样式
   ============================================ */

