.zjpcy-splitter-horizontal .zjpcy-splitter__bar {
  cursor: col-resize;
  width: var(--zjpcy-splitter-bar-size);
  height: 100%;
  min-height: 100%;
  align-self: stretch;
}

/* 垂直分割条 */

.zjpcy-splitter-vertical .zjpcy-splitter__bar {
  cursor: row-resize;
  width: 100%;
  height: var(--zjpcy-splitter-bar-size);
  min-width: 100%;
  align-self: stretch;
}

/* 分割条悬停状态 - 渐变背景和阴影增强 */

.zjpcy-splitter__bar:not(.zjpcy-splitter__bar-disabled):hover {
