portant;\n  z-index: 1051 !important;\n  pointer-events: none !important;\n}\n\n.dropdown-menu-visible .dropdown-menu--right {\n  transform: translateX(0) scale(1) !important;\n  pointer-events: auto !important;\n  animation: dropdownBounceInRight 0.35s cubic-bezier(0.23, 1, 0.32, 1);\n}\n\n@keyframes dropdownBounceInRight {\n  0% {\n    opacity: 0;\n    transform: translateX(-8px) scale(0.96);\n  }\n  50% {\n    transform: translateX(2px) scale(1.01);\n  }\n  100% {\n    opacity: 1;\n    transform: translateX(0) scale(1);\n  }\n}\n\n.dropdown-menu--right::before {\n  left: -8px;\n  top: 12px;\n  transform: none;\n  border-left: 8px solid var(--zjpcy-bg-color-white);\n  border-right: none;\n  border-top: 8px solid transparent;\n  border-bottom: 8px solid transparent;\n}\n\n.dropdown-menu--right::after {\n  left: -9px;\n  top: 11px;\n  transform: none;\n  border-left: 9px solid var(--zjpcy-border-color-light);\n  border-right: none;\n  border-top: 9px solid transparent;\n  border-bottom: 9px solid transparent;\n}\n\n/* ============================================\n   下拉列表\n   ============================================ */\n\n.dropdown-list {\n  margin: 0;\n  padding: 4px 0;\n  list-style: none;\n}\n\n/* ============================================\n   下拉项\n   ============================================ */\n\n.dropdown-item {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 16px;\n  cursor: pointer;\n  transition: all var(--zjpcy-transition-duration) ease;\n  min-width: 0;\n  color: var(--zjpcy-text-color);\n  font-size: 14px;\n}\n\n.dropdown-item:hover {\n  background: var(--zjpcy-primary-light-color);\n  color: var(--zjpcy-primary-color);\n}\n\n.dropdown-item--disabled {\n  color: var(--zjpcy-text-color-light);\n  cursor: not-allowed;\n  opacity: var(--zjpcy-opacity-disabled);\n}\n\n.dropdown-item--disabled:hover {\n  background: transparent;\n  color: var(--zjpcy-text-color-light);\n}\n\n/* ============================================\n   下拉