tem {\n  display: flex;\n  align-items: center;\n  height: 40px;\n  padding: 0px;\n  cursor: pointer;\n  transition: all var(--zjpcy-transition-duration, 0.2s) var(--zjpcy-transition-timing-function, ease-in-out);\n  border-radius: var(--zjpcy-border-radius-sm, 4px);\n  margin: 4px 0;\n  -webkit-user-select: none;\n     -moz-user-select: none;\n          user-select: none;\n  position: relative;\n  overflow: hidden;\n}\n\n/* 水波纹效果 */\n\n.zjpcy-menu-item::after {\n  content: '';\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 0;\n  height: 0;\n  background: radial-gradient(circle, var(--zjpcy-primary-light-color, rgba(24, 144, 255, 0.1)) 0%, transparent 70%);\n  border-radius: 50%;\n  transform: translate(-50%, -50%);\n  transition: width 0.4s ease, height 0.4s ease, opacity 0.4s ease;\n  opacity: 0;\n  pointer-events: none;\n}\n\n.zjpcy-menu-item:active::after {\n  width: 200%;\n  height: 200%;\n  opacity: 1;\n  transition: width 0.2s ease, height 0.2s ease, opacity 0.1s ease;\n}\n\n/* ============================================\n   Light 主题样式 - 使用组合类名\n   ============================================ */\n\n.zjpcy-menu-item-light {\n  color: var(--zjpcy-text-color, rgba(0, 0, 0, 0.85));\n}\n\n.zjpcy-menu-item-light:hover:not(.zjpcy-menu-item-disabled) {\n  background-color: var(--zjpcy-primary-light-color, rgba(24, 144, 255, 0.06));\n  color: var(--zjpcy-primary-color, #1890ff);\n}\n\n.zjpcy-menu-item-light-selected {\n  background-color: var(--zjpcy-primary-light-color, rgba(24, 144, 255, 0.12));\n  color: var(--zjpcy-primary-color, #1890ff);\n  font-weight: 600;\n}\n\n/* 垂直/内联模式下的选中样式 - 带左侧阴影 */\n\n.zjpcy-menu-item-light-selected-vertical {\n  box-shadow: inset 3px 0 0 var(--zjpcy-primary-color, #1890ff);\n}\n\n.zjpcy-menu-item-light-selected:hover {\n  background-color: var(--zjpcy-primary-light-color, rgba(24, 144, 255, 0.18));\n}\n\n.zjpcy-menu-item-light-selected-vertical:hover {\n  background-color: var(--zjpcy-primary-light-color, rgba(24, 144, 2