color-tertiary, rgba(0, 0, 0, 0.45));\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  line-height: 1.3;\n  margin-top: 2px;\n}\n\n.zjpcy-menu-item:hover .zjpcy-menu-item-description {\n  color: var(--zjpcy-primary-color, #1890ff);\n  opacity: 0.8;\n}\n\n/* ============================================\n   折叠状态下的缩略标签 - 使用组合类名\n   ============================================ */\n\n.zjpcy-menu-item-collapsed-label {\n  width: 24px;\n  height: 24px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 14px;\n  font-weight: 700;\n  background: linear-gradient(135deg, var(--zjpcy-primary-color, #1890ff) 0%, var(--zjpcy-primary-hover-color, #40a9ff) 100%);\n  color: var(--zjpcy-bg-color-white, #fff);\n  border-radius: 6px;\n  margin: 0 auto;\n  box-shadow: 0 2px 6px rgba(24, 144, 255, 0.25);\n  letter-spacing: 0.5px;\n  flex-shrink: 0;\n  transition: all 0.2s ease;\n}\n\n/* 折叠状态下悬停效果 */\n\n.zjpcy-menu-item:hover .zjpcy-menu-item-collapsed-label {\n  transform: scale(1.05);\n  box-shadow: 0 3px 8px rgba(24, 144, 255, 0.35);\n}\n\n/* Dark 主题下折叠标签 */\n\n.zjpcy-menu-item-dark .zjpcy-menu-item-collapsed-label {\n  background: linear-gradient(135deg, rgba(255, 255, 255, 0.9) 0%, rgba(255, 255, 255, 0.75) 100%);\n  color: var(--zjpcy-primary-color, #1890ff);\n  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);\n}\n\n.zjpcy-menu-item-dark:hover .zjpcy-menu-item-collapsed-label {\n  background: linear-gradient(135deg, #fff 0%, rgba(255, 255, 255, 0.9) 100%);\n  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.25);\n}\n\n/* 选中状态下的折叠标签 */\n\n.zjpcy-menu-item-selected .zjpcy-menu-item-collapsed-label {\n  box-shadow: 0 2px 6px rgba(24, 144, 255, 0.4);\n}\n\n.zjpcy-menu-item-selected:hover .zjpcy-menu-item-collapsed-label {\n  box-shadow: 0 3px 8px rgba(24, 144, 255, 0.5);\n}\n\n/* Dark 主题选中状态下的折叠标签 */\n\n.zjpcy-menu-item-dark-selected .zjpcy-menu-item-collapsed-label {\n  background: linear-gradient(135deg, #fff 0%, #fff 100%);\n  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);\n}\n\n/* ============================================\n   菜单项箭头 - 使用组合类名\n   ============================================ */\n\n.zjpcy-menu-item-arrow {\n  display: flex;\n  align-items: center;\n  margin-left: 8px;\n  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1), color var(--zjpcy-transition-duration, 0.2s) ease;\n  flex-shrink: 0;\n}\n\n.zjpcy-menu-item-arrow-open {\n  transform: rotate(180deg);\n}\n\n.zjpcy-menu-item-arrow-horizontal {\n  transform: rotate(-90deg);\n}\n\n.zjpcy-menu-item-arrow-horizontal-open {\n  transform: rotate(0deg);\n}\n\n/* ============================================\n   滚动条样式 - Dark 主题\n   ============================================ */\n\n.zjpcy-menu-dark::-webkit-scrollbar {\n  width: 4px;\n  height: 6px;\n}\n\n.zjpcy-menu-dark::-webkit-scrollbar-track {\n  background: transparent;\n}\n\n.zjpcy-menu-dark::-webkit-scrollbar-thumb {\n  background-color: color-mix(in srgb, var(--zjpcy-primary-color, #1890ff) 50%, transparent);\n  border-radius: var(--zjpcy-border-radius-sm, 4px);\n  -webkit-transition: background-color var(--zjpcy-transition-duration, 0.2s) ease;\n  transition: background-color var(--zjpcy-transition-duration, 0.2s) ease;\n}\n\n.zjpcy-menu-dark::-webkit-scrollbar-thumb:hover {\n  background-color: color-mix(in srgb, var(--zjpcy-primary-color, #1890ff) 70%, transparent);\n}\n\n.zjpcy-menu-dark {\n  scrollbar-width: thin;\n  scrollbar-color: color-mix(in srgb, var(--zjpcy-primary-color, #1890ff) 50%, transparent) transparent;\n}\n\n/* ============================================\n   扁平垂直模式 (Vertical Flat)\n   ============================================ */\n\n.zjpcy-menu-vertical-flat {\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n  min-width: 200px;\n}\n\n/* 扁平模式下子菜单容器始终可见 - 使用组合类名 */\n\n.zjpcy-menu-submenu-wrapper-vertical-flat {\n  position: relative;\n  width: 100%;\n}\n\n/* 扁平模式子菜单 - 无展开/关闭动画，直接显示 */\n\n.zjpcy-menu-submenu-vertical-flat {\n  overflow: visible;\n  